INSERT INTO categories (id, name, description) VALUES ('computer-awareness', 'Computer Awareness / IT', 'Computer fundamentals, networking, and IT general knowledge — a frequent section in Banking/SSC exams.');
INSERT INTO question_sets (id, owner_user_id, title, track, visibility, created_at, approved_at, approved_by) VALUES ('computer-awareness-bank', NULL, 'Computer Awareness Prep', 'computer-awareness', 'shared', '2026-11-14T06:17:56.365Z', '2026-11-14T06:17:56.365Z', NULL);
INSERT INTO question_set_categories (set_id, category_id) VALUES ('computer-awareness-bank', 'computer-awareness');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00001', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 0, 'What does CPU stand for, and what is its primary function?', '`CPU` stands for **Central Processing Unit**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00002', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 1, 'What are the three main components of a CPU?', '- `ALU` (**Arithmetic Logic Unit**) — performs arithmetic and logical operations
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00003', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 2, 'What is the difference between RAM and ROM?', '`RAM` (**Random Access Memory**) is **volatile**, meaning its contents are lost when power is switched off; it is used for temporary storage of data and programs currently in use.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00004', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 3, 'What is the full form of BIOS and what does it do?', '`BIOS` stands for **Basic Input Output System**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00005', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 4, 'What has largely replaced BIOS in modern computers?', '`UEFI` (**Unified Extensible Firmware Interface**) has replaced traditional `BIOS` in most modern systems.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00006', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 5, 'What is the difference between primary memory and secondary memory?', '**Primary memory** (such as `RAM` and cache) is directly accessible by the `CPU`, is typically volatile, and is faster but smaller in capacity.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00007', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 6, 'What is cache memory?', '**Cache memory** is a small, very fast memory located close to or inside the `CPU` that stores frequently used data and instructions.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00008', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 7, 'What is the function of registers in a CPU?', '**Registers** are the fastest storage locations available to the `CPU`, used to hold data, instructions, and addresses that are being actively processed.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00009', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 8, 'What is a motherboard?', 'A **motherboard** is the main circuit board of a computer that connects and allows communication between the `CPU`, memory, storage devices, and peripherals.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00010', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 9, 'What is the difference between an input device and an output device? Give one example of each.', 'An **input device** is used to feed data and instructions into a computer, such as a **keyboard**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00011', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 10, 'Name three examples each of input and output devices used in computing.', '**Input devices**:
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00012', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 11, 'What is a hard disk drive (HDD)?', 'A **Hard Disk Drive (`HDD`)** is a secondary storage device that uses **magnetic storage** on rotating platters to store data permanently.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00013', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 12, 'What is a Solid State Drive (SSD) and how does it differ from an HDD?', 'A **Solid State Drive (`SSD`)** stores data using **flash memory** with no moving mechanical parts, unlike a `HDD` which uses spinning magnetic platters.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00014', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 13, 'What is the function of a GPU?', 'A `GPU` (**Graphics Processing Unit**) is a specialized processor designed to **render images, video, and animations** by performing many parallel calculations simultaneously.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00015', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 14, 'What is Moore''s Law?', '**Moore''s Law** is an observation made by Intel co-founder **Gordon Moore** in 1965 that the **number of transistors on a microchip doubles approximately every two years**, while the cost of computers halves.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00016', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 15, 'What is the difference between a bit and a byte?', 'A **bit** (binary digit) is the smallest unit of data in computing, representing either a `0` or a `1`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00017', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 16, 'Arrange in increasing order: bit, byte, kilobyte, megabyte, gigabyte, terabyte.', 'The **increasing order** of data storage units is:
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00018', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 17, 'What is the clock speed of a processor measured in?', '**Clock speed** is measured in **Hertz (`Hz`)**, most commonly expressed in **gigahertz (`GHz`)** for modern processors.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00019', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 18, 'What is a dual-core or multi-core processor?', 'A **multi-core processor** contains **two or more independent processing units (cores)** on a single chip, allowing it to execute multiple instructions simultaneously.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00020', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 19, 'What is an embedded system?', 'An **embedded system** is a combination of computer hardware and software **designed for a specific, dedicated function** within a larger mechanical or electrical system.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00021', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 20, 'What is the difference between analog and digital computers?', '**Analog computers** process continuously varying data (like voltage or temperature) and are used for specialized scientific measurements.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00022', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 21, 'What are the five generations of computers based on technology used?', '- **First Generation** (1940s-50s): **Vacuum tubes**
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00023', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 22, 'Which generation of computers introduced the microprocessor?', 'The **Fourth Generation** of computers introduced the **microprocessor**, where an entire `CPU` was fabricated onto a single integrated circuit chip.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00024', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 23, 'What is the function of the control unit (CU) in a CPU?', 'The **Control Unit (`CU`)** directs and coordinates the activities of all other components of the computer.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00025', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 24, 'What is a motherboard chipset?', 'A **chipset** is a set of electronic components on the motherboard that **manages data flow** between the `CPU`, memory, storage, and peripheral devices.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00026', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 25, 'What is the difference between volatile and non-volatile memory?', '**Volatile memory** (like `RAM`) **loses its stored data when power is removed**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00027', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 26, 'What is a USB port and what does USB stand for?', '`USB` stands for **Universal Serial Bus**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00028', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 27, 'What are the common USB connector types and their general characteristics?', 'Common `USB` types include:
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00029', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 28, 'What is the function of a sound card?', 'A **sound card** is an expansion card (or integrated chip) that enables a computer to **input and output audio signals** to speakers, microphones, and headphones.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00030', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 29, 'What is a network interface card (NIC)?', 'A **Network Interface Card (`NIC`)** is a hardware component that allows a computer to **connect to a network**, either through a wired **Ethernet** connection or wirelessly via **Wi-Fi**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00031', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 30, 'What is a MAC address?', 'A `MAC` (**Media Access Control**) address is a **unique 48-bit hardware identifier** assigned to a network interface card by its manufacturer.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00032', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 31, 'What is the function of a power supply unit (PSU) in a computer?', 'A **Power Supply Unit (`PSU`)** converts **AC (alternating current)** from a wall outlet into the **DC (direct current)** voltages required by the computer''s internal components, such as the motherboard, `CPU`, and drives.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00033', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 32, 'What is the difference between an optical disk and a magnetic disk?', 'An **optical disk** (such as a `CD`, `DVD`, or `Blu-ray` disc) stores data using microscopic pits read by a **laser beam**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00034', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 33, 'What does DVD stand for and what is its typical storage capacity?', '`DVD` stands for **Digital Versatile Disc** (originally Digital Video Disc).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00035', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 34, 'What is a flash drive (pen drive)?', 'A **flash drive** (or pen drive) is a **portable storage device** that uses **flash memory** to store data, connecting to a computer via a `USB` port.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00036', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 35, 'What is the function of a scanner?', 'A **scanner** is an input device that **converts physical documents, images, or photographs into digital format** by capturing and digitizing the image.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00037', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 36, 'What is an inkjet printer and how does it differ from a laser printer?', 'An **inkjet printer** sprays tiny droplets of **liquid ink** onto paper to form images and text, and is generally cheaper to buy but costlier per page for high volumes.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00038', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 37, 'What is the function of a webcam?', 'A **webcam** is an input device that **captures live video and images**, commonly used for video conferencing, online meetings, and recording.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00039', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 38, 'What is an OCR device/technology?', '`OCR` stands for **Optical Character Recognition**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00040', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 39, 'What is the difference between a joystick and a trackball?', 'A **joystick** is an input device with a stick that pivots to control movement or direction, commonly used in **gaming**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00041', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 40, 'What is a barcode reader used for?', 'A **barcode reader** is an optical input device that **scans and decodes barcodes** (patterns of parallel lines or patterns) to quickly retrieve associated product or item information, widely used in retail billing and inventory management.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00042', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 41, 'What is a plotter?', 'A **plotter** is an output device that produces **high-quality vector graphics**, such as engineering drawings, architectural plans, and large-format graphics, by moving a pen (or using ink/laser) across paper.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00043', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 42, 'What is the function of RAM slots (DIMM slots) on a motherboard?', '**DIMM (Dual In-line Memory Module) slots** on a motherboard are where `RAM` modules are physically installed.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00044', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 43, 'What does DDR stand for in the context of RAM?', '`DDR` stands for **Double Data Rate**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00045', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 44, 'What is the difference between a CRT monitor and an LCD monitor?', 'A `CRT` (**Cathode Ray Tube**) monitor uses an **electron gun** to excite phosphors on a screen, making it bulky and heavy.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00046', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 45, 'What is the function of an expansion slot (like PCIe) on a motherboard?', 'An **expansion slot**, such as `PCIe` (**Peripheral Component Interconnect Express**), allows additional hardware cards — like graphics cards, sound cards, or network cards — to be **installed and connected** to the motherboard to extend system capabilities.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00047', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 46, 'What is firmware?', '**Firmware** is a type of software **permanently programmed into a hardware device''s non-volatile memory** (such as `ROM` or flash memory).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00048', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 47, 'What is the difference between serial and parallel data transmission?', '**Serial transmission** sends data **one bit at a time** over a single communication line, which is simpler and better suited for long distances.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00049', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 48, 'What is the function of a heat sink in a computer?', 'A **heat sink** is a passive cooling component, usually made of aluminum or copper, that **absorbs and dissipates heat** generated by the `CPU` or `GPU`, often paired with a fan to maintain safe operating temperatures.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00050', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 49, 'What is the booting process of a computer?', '**Booting** is the process of starting a computer, where the `BIOS`/`UEFI` performs a **POST (Power-On Self-Test)**, then locates and loads the **bootloader**, which in turn loads the **operating system kernel** into memory.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00051', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 50, 'What does POST stand for in computing?', '`POST` stands for **Power-On Self-Test**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00052', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 51, 'What is the von Neumann architecture?', 'The **von Neumann architecture**, proposed by **John von Neumann**, describes a computer design in which **both program instructions and data are stored in the same memory** and use the same bus for transfer.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00053', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 52, 'How does Harvard architecture differ from von Neumann architecture?', 'In **Harvard architecture**, **separate memory and buses are used for instructions and data**, allowing simultaneous access to both.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00054', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 53, 'What is the difference between a supercomputer and a mainframe computer?', 'A **supercomputer** is designed for extremely **high-speed, complex numerical calculations**, such as weather forecasting or scientific simulations.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00055', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 54, 'What is PARAM, in the context of Indian supercomputers?', '**PARAM** is a series of **supercomputers developed in India** by the **Centre for Development of Advanced Computing (`C-DAC`)**, starting with `PARAM 8000` in 1991.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00056', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 55, 'What is the function of an uninterruptible power supply (UPS)?', 'A `UPS` (**Uninterruptible Power Supply**) provides **emergency backup power** to connected equipment when the main power source fails, using an internal battery, giving time to save work or allow a safe shutdown.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00057', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 56, 'What is the difference between a laptop and a desktop computer in terms of components?', 'A **laptop** integrates the monitor, keyboard, touchpad, battery, and all components into a **single portable unit**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00058', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 57, 'What is a dot matrix printer?', 'A **dot matrix printer** is an impact printer that creates characters and images by **striking pins against an ink ribbon** onto paper, forming patterns of dots.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00059', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 58, 'What is the difference between touchscreen and touchpad?', 'A **touchscreen** is a display that allows direct interaction by **touching the screen itself** with a finger or stylus.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00060', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 59, 'What is the function of an optical mouse sensor?', 'An **optical mouse** uses a **small `LED` or laser light and an image sensor** to detect movement relative to the surface beneath it, converting that motion into cursor movement on screen, without needing a mechanical ball.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00061', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 60, 'What is the function of the system clock (oscillator) in a computer?', 'The **system clock**, driven by a **quartz crystal oscillator**, generates **regular electrical pulses** that synchronize the operations of the `CPU` and other components, with clock speed determining how many operations occur per second.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00062', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 61, 'What is a bus in computer architecture?', 'A **bus** is a communication pathway that transfers data between components inside a computer.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00063', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 62, 'What is the typical function of an Ethernet port on a computer?', 'An **Ethernet port** is a physical connector (usually `RJ-45`) used to connect a computer to a **wired local area network (`LAN`)** using an Ethernet cable, enabling internet and network access.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00064', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 63, 'What is the difference between a megapixel and resolution in the context of cameras/displays?', 'A **megapixel** refers to **one million pixels**, often used to describe a camera sensor''s total pixel count.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00065', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 64, 'What is the function of a modem?', 'A **modem** (**modulator-demodulator**) converts digital data from a computer into **analog signals** for transmission over telephone or cable lines, and converts incoming analog signals back into digital data, enabling internet connectivity.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00066', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 65, 'What is the difference between a modem and a router?', 'A **modem** connects a home or office network to the **internet service provider (`ISP`)**, translating signals between the `ISP`''s network and the local network.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00067', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 66, 'What is the IEEE standard number for Ethernet?', 'The `IEEE 802.3` standard defines the specifications for **Ethernet**, the most widely used wired `LAN` technology.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00068', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 67, 'What is a dual in-line memory module (DIMM)?', 'A `DIMM` (**Dual In-line Memory Module**) is the standard physical form factor for modern `RAM` modules, featuring **separate electrical contacts on each side** of the module, used in desktops and servers.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00069', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 68, 'What is the function of a RAID controller/configuration?', '`RAID` stands for **Redundant Array of Independent Disks**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00070', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 69, 'What is the typical storage capacity measurement hierarchy between a terabyte and a petabyte?', 'A **petabyte (`PB`)** equals **1024 terabytes (`TB`)**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00071', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 70, 'What is the function of the BIOS/UEFI settings menu, and how is it typically accessed?', 'The `BIOS`/`UEFI` settings menu allows users to **configure hardware settings** such as boot order, system time, and security options.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00072', 'computer-awareness-bank', 'Computer Fundamentals & Hardware', 0, 71, 'What is the difference between internal and external hard drives?', 'An **internal hard drive** is mounted inside the computer case and connected directly to the motherboard, typically via a `SATA` interface.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00073', 'computer-awareness-bank', 'Software & Operating Systems', 1, 0, 'What is an operating system (OS)?', 'An **Operating System (`OS`)** is **system software** that manages computer hardware and software resources, and provides common services for application programs.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00074', 'computer-awareness-bank', 'Software & Operating Systems', 1, 1, 'What is the difference between system software and application software?', '**System software** manages and controls computer hardware so that application software can run, for example an **operating system** or a **device driver**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00075', 'computer-awareness-bank', 'Software & Operating Systems', 1, 2, 'Name three examples of operating systems.', 'Three widely used **operating systems** are:
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00076', 'computer-awareness-bank', 'Software & Operating Systems', 1, 3, 'What is the kernel of an operating system?', 'The **kernel** is the **core component** of an operating system that has complete control over the system, managing `CPU`, memory, and device operations.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00077', 'computer-awareness-bank', 'Software & Operating Systems', 1, 4, 'What is multitasking in an operating system?', '**Multitasking** is the ability of an operating system to **execute multiple tasks or processes seemingly simultaneously** by rapidly switching the `CPU`''s attention between them.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00078', 'computer-awareness-bank', 'Software & Operating Systems', 1, 5, 'What is the difference between multitasking and multiprocessing?', '**Multitasking** runs multiple processes on a **single processor** by rapidly switching between them.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00079', 'computer-awareness-bank', 'Software & Operating Systems', 1, 6, 'What is multithreading?', '**Multithreading** is the ability of a `CPU`, or a single program, to execute **multiple threads (smaller units of a process) concurrently**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00080', 'computer-awareness-bank', 'Software & Operating Systems', 1, 7, 'What is virtual memory?', '**Virtual memory** is a memory management technique that uses **hard disk space to extend the apparent amount of `RAM`** available to the system.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00081', 'computer-awareness-bank', 'Software & Operating Systems', 1, 8, 'What is a device driver?', 'A **device driver** is a specialized piece of software that allows the operating system to **communicate with and control a specific hardware device**, such as a printer, graphics card, or mouse.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00082', 'computer-awareness-bank', 'Software & Operating Systems', 1, 9, 'What is the function of the file system in an operating system?', 'A **file system** organizes and manages how **data is stored, named, and retrieved** on a storage device.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00083', 'computer-awareness-bank', 'Software & Operating Systems', 1, 10, 'What does NTFS stand for?', '`NTFS` stands for **New Technology File System**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00084', 'computer-awareness-bank', 'Software & Operating Systems', 1, 11, 'What is the difference between FAT32 and NTFS file systems?', '`FAT32` (**File Allocation Table 32**) is an older file system with a **maximum file size limit of 4 GB** and limited security features, but it is widely compatible across devices.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00085', 'computer-awareness-bank', 'Software & Operating Systems', 1, 12, 'What is an open-source operating system? Give an example.', 'An **open-source operating system** has its **source code made publicly available**, allowing anyone to view, modify, and distribute it.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00086', 'computer-awareness-bank', 'Software & Operating Systems', 1, 13, 'Who is considered the creator of the Linux kernel?', '**Linus Torvalds** created the **Linux kernel**, first releasing it in **1991** as a free and open-source alternative inspired by `Unix`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00087', 'computer-awareness-bank', 'Software & Operating Systems', 1, 14, 'What is a GUI in the context of operating systems?', '`GUI` stands for **Graphical User Interface**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00088', 'computer-awareness-bank', 'Software & Operating Systems', 1, 15, 'What is the difference between GUI and CLI?', 'A `GUI` (**Graphical User Interface**) allows interaction through **visual elements** like icons and windows, using a mouse or touch.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00089', 'computer-awareness-bank', 'Software & Operating Systems', 1, 16, 'What is booting and what is the difference between a cold boot and a warm boot?', '**Booting** is the process of **starting up a computer** and loading the operating system into memory.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00090', 'computer-awareness-bank', 'Software & Operating Systems', 1, 17, 'What is a utility software? Give an example.', '**Utility software** is designed to help **analyze, configure, optimize, or maintain** a computer system.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00091', 'computer-awareness-bank', 'Software & Operating Systems', 1, 18, 'What is the difference between freeware and shareware?', '**Freeware** is software made available **free of cost**, with no payment required for its use.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00092', 'computer-awareness-bank', 'Software & Operating Systems', 1, 19, 'What is open-source software?', '**Open-source software** is software whose **source code is publicly accessible**, allowing users to view, modify, and distribute it, often under a specific open-source license.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00093', 'computer-awareness-bank', 'Software & Operating Systems', 1, 20, 'What is proprietary software?', '**Proprietary software** is software owned by an individual or company that **restricts** the use, modification, or redistribution of its source code, typically requiring a license or purchase to use.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00094', 'computer-awareness-bank', 'Software & Operating Systems', 1, 21, 'What is firmware, and how does it differ from an operating system?', '**Firmware** is low-level software **permanently embedded in hardware** (such as `BIOS`/`UEFI`) that controls specific device functions.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00095', 'computer-awareness-bank', 'Software & Operating Systems', 1, 22, 'What is a compiler?', 'A **compiler** is a program that **translates source code written in a high-level programming language into machine code (or an intermediate code)** all at once, before the program is executed.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00096', 'computer-awareness-bank', 'Software & Operating Systems', 1, 23, 'What is an interpreter, and how does it differ from a compiler?', 'An **interpreter** translates and executes source code **line by line**, without producing a separate standalone executable file.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00097', 'computer-awareness-bank', 'Software & Operating Systems', 1, 24, 'What is an assembler?', 'An **assembler** is a program that translates code written in **assembly language** (a low-level, human-readable symbolic language) into **machine code** that a computer''s processor can directly execute.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00098', 'computer-awareness-bank', 'Software & Operating Systems', 1, 25, 'What is the difference between a process and a program?', 'A **program** is a **passive set of instructions** stored on disk.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00099', 'computer-awareness-bank', 'Software & Operating Systems', 1, 26, 'What is deadlock in an operating system?', 'A **deadlock** occurs when two or more processes are **each waiting for a resource held by the other**, resulting in neither process being able to proceed, effectively halting progress indefinitely.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00100', 'computer-awareness-bank', 'Software & Operating Systems', 1, 27, 'What is process scheduling in an operating system?', '**Process scheduling** is the method by which an operating system **decides which process runs on the `CPU` at a given time**, using algorithms such as **First-Come-First-Served (`FCFS`), Round Robin, and Shortest Job First (`SJF`)**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00101', 'computer-awareness-bank', 'Software & Operating Systems', 1, 28, 'What is the role of an operating system''s memory management function?', '**Memory management** in an operating system involves **allocating and deallocating memory space** to processes as needed, tracking which parts of memory are in use, and optimizing the use of `RAM` through techniques like **paging and virtual memory**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00102', 'computer-awareness-bank', 'Software & Operating Systems', 1, 29, 'What is Safe Mode in Windows?', '**Safe Mode** is a diagnostic startup mode in Windows that loads the operating system with **only essential drivers and services**, used for **troubleshooting problems** such as malware infections or faulty drivers.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00103', 'computer-awareness-bank', 'Software & Operating Systems', 1, 30, 'What is Task Manager used for in Windows?', '**Task Manager** is a system utility in Windows that lets users **view and manage running processes, applications, and system performance** (`CPU`, memory, disk, and network usage), and allows ending unresponsive tasks.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00104', 'computer-awareness-bank', 'Software & Operating Systems', 1, 31, 'What is Device Manager used for in Windows?', '**Device Manager** is a Windows utility that allows users to **view and manage the hardware devices** connected to a computer, including updating, disabling, or troubleshooting **device drivers**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00105', 'computer-awareness-bank', 'Software & Operating Systems', 1, 32, 'What is Disk Defragmentation?', '**Disk Defragmentation** is the process of **reorganizing fragmented data** on a hard disk so that related pieces of files are stored contiguously, which can improve read/write performance on traditional `HDD`s (it is not needed on `SSD`s).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00106', 'computer-awareness-bank', 'Software & Operating Systems', 1, 33, 'What is a software license? Name one common type.', 'A **software license** is a legal agreement specifying the **terms under which software can be used, copied, or distributed**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00107', 'computer-awareness-bank', 'Software & Operating Systems', 1, 34, 'What is the difference between 32-bit and 64-bit operating systems?', 'A **32-bit operating system** can typically address a **maximum of about 4 GB of RAM** and uses 32-bit data paths.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00108', 'computer-awareness-bank', 'Software & Operating Systems', 1, 35, 'What is the Windows Registry?', 'The **Windows Registry** is a **hierarchical database** that stores low-level settings and configuration information for the Windows operating system, hardware, and installed applications.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00109', 'computer-awareness-bank', 'Software & Operating Systems', 1, 36, 'What is a service pack / patch / update in software maintenance?', 'A **patch** or **update** is a piece of software designed to **fix bugs, close security vulnerabilities, or add minor improvements** to an existing program.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00110', 'computer-awareness-bank', 'Software & Operating Systems', 1, 37, 'What is an API?', '`API` stands for **Application Programming Interface**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00111', 'computer-awareness-bank', 'Software & Operating Systems', 1, 38, 'What is middleware?', '**Middleware** is software that acts as a **bridge between an operating system or database and applications**, especially on a network, enabling communication and data management across distributed systems.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00112', 'computer-awareness-bank', 'Software & Operating Systems', 1, 39, 'What is the purpose of an antivirus software?', '**Antivirus software** is designed to **detect, prevent, and remove malicious software** (malware) such as viruses, worms, and trojans from a computer system, typically through signature-based scanning and real-time monitoring.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00113', 'computer-awareness-bank', 'Software & Operating Systems', 1, 40, 'What is the difference between system software and utility software?', '**System software** (like an operating system) is essential for running the computer and managing hardware directly.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00114', 'computer-awareness-bank', 'Software & Operating Systems', 1, 41, 'What is a bootloader?', 'A **bootloader** is a small program that **loads the operating system kernel into memory** during the startup process, after the `BIOS`/`UEFI` completes its initial hardware checks. `GRUB` is a common bootloader used in Linux systems.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00115', 'computer-awareness-bank', 'Software & Operating Systems', 1, 42, 'What is the significance of the term ''distro'' in Linux?', 'A **''distro''** (short for **distribution**) is a specific **packaged version of the Linux operating system**, bundling the Linux kernel with a selection of software, utilities, and a package manager.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00116', 'computer-awareness-bank', 'Software & Operating Systems', 1, 43, 'What is Android, and who develops it?', '**Android** is a **mobile operating system** based on a modified version of the Linux kernel, developed primarily by **Google**, and used widely on smartphones and tablets.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00117', 'computer-awareness-bank', 'Software & Operating Systems', 1, 44, 'What is iOS, and who develops it?', '**iOS** is the mobile operating system developed by **Apple Inc.**, used exclusively on **iPhone** devices.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00118', 'computer-awareness-bank', 'Software & Operating Systems', 1, 45, 'What is the function of a hypervisor in virtualization?', 'A **hypervisor** is software that creates and runs **virtual machines (`VM`s)**, allowing multiple operating systems to run on a single physical hardware host by allocating and managing its resources.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00119', 'computer-awareness-bank', 'Software & Operating Systems', 1, 46, 'What is the difference between Type 1 and Type 2 hypervisors?', 'A **Type 1 hypervisor** (bare-metal) runs **directly on the host''s hardware** without an underlying operating system, commonly used in enterprise servers (e.g., `VMware ESXi`).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00120', 'computer-awareness-bank', 'Software & Operating Systems', 1, 47, 'What is cloud computing?', '**Cloud computing** is the delivery of **computing services — servers, storage, databases, software — over the internet** (''the cloud''), allowing users to access resources on-demand without owning the physical infrastructure.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00121', 'computer-awareness-bank', 'Software & Operating Systems', 1, 48, 'What are the three main cloud computing service models (SaaS, PaaS, IaaS)?', '- `SaaS` (**Software as a Service**): ready-to-use software delivered over the internet, e.g., `Gmail`
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00122', 'computer-awareness-bank', 'Software & Operating Systems', 1, 49, 'What is the difference between public cloud, private cloud, and hybrid cloud?', 'A **public cloud** offers services over the internet shared among multiple organizations, such as `AWS` or `Microsoft Azure`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00123', 'computer-awareness-bank', 'Software & Operating Systems', 1, 50, 'What is a software bug?', 'A **bug** is an **error, flaw, or fault** in a computer program that causes it to produce incorrect or unexpected results, or to behave in unintended ways.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00124', 'computer-awareness-bank', 'Software & Operating Systems', 1, 51, 'What is beta testing in software development?', '**Beta testing** is a phase of software testing in which a **nearly finished product is released to a limited group of external users** to identify bugs and gather feedback before the final public release.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00125', 'computer-awareness-bank', 'Software & Operating Systems', 1, 52, 'What is the Software Development Life Cycle (SDLC)?', 'The **Software Development Life Cycle (`SDLC`)** is a structured process for **planning, creating, testing, and deploying software**, typically including phases such as requirement analysis, design, implementation, testing, deployment, and maintenance.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00126', 'computer-awareness-bank', 'Software & Operating Systems', 1, 53, 'What is an operating system shell?', 'A **shell** is the **user interface** layer of an operating system that interprets and executes user commands, acting as an intermediary between the user and the kernel.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00127', 'computer-awareness-bank', 'Software & Operating Systems', 1, 54, 'What is the function of a spooler in printing?', 'A **print spooler** is software that **manages print jobs sent to a printer**, queuing them and sending them to the printer in order, allowing the user to continue other tasks while printing happens in the background.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00128', 'computer-awareness-bank', 'Software & Operating Systems', 1, 55, 'What is a real-time operating system (RTOS)?', 'A **Real-Time Operating System (`RTOS`)** is designed to process data and respond to inputs **within a strict, guaranteed time constraint**, commonly used in embedded systems like industrial controllers and medical devices.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00129', 'computer-awareness-bank', 'Software & Operating Systems', 1, 56, 'What is batch processing in operating systems?', '**Batch processing** is a method where a **series of jobs are collected and processed together without user interaction**, typically used for repetitive tasks like payroll processing, common in early operating systems.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00130', 'computer-awareness-bank', 'Software & Operating Systems', 1, 57, 'What is the difference between a single-user and a multi-user operating system?', 'A **single-user operating system** allows **only one user to operate** the computer at a time, such as early versions of Windows.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00131', 'computer-awareness-bank', 'Software & Operating Systems', 1, 58, 'What is the difference between an operating system update and a driver update?', 'An **operating system update** modifies the **core OS files** to fix bugs, patch security issues, or add features system-wide.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00132', 'computer-awareness-bank', 'Software & Operating Systems', 1, 59, 'What is the purpose of a recycle bin / trash in an OS?', 'The **Recycle Bin** (Windows) or **Trash** (macOS/Linux) is a temporary storage area where **deleted files are held** before permanent removal, allowing users to recover accidentally deleted items.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00133', 'computer-awareness-bank', 'Software & Operating Systems', 1, 60, 'What is the function of the clipboard in an operating system?', 'The **clipboard** is a temporary storage area in memory used to **hold data that has been cut or copied**, so it can be **pasted** elsewhere within the same application or across different applications.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00134', 'computer-awareness-bank', 'Software & Operating Systems', 1, 61, 'What is a software suite? Give an example.', 'A **software suite** is a **collection of related application programs bundled together** and sold or distributed as a single package.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00135', 'computer-awareness-bank', 'Software & Operating Systems', 1, 62, 'What is plug and play (PnP) in the context of operating systems?', '**Plug and Play (`PnP`)** is a feature that allows an operating system to **automatically detect and configure hardware devices** when they are connected, without requiring manual driver installation or configuration by the user.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00136', 'computer-awareness-bank', 'Software & Operating Systems', 1, 63, 'What is the Blue Screen of Death (BSOD)?', 'The **Blue Screen of Death (`BSOD`)** is an **error screen displayed by Windows** after a fatal system crash, typically caused by hardware failure, driver issues, or critical software errors, requiring a restart.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00137', 'computer-awareness-bank', 'Software & Operating Systems', 1, 64, 'What is the purpose of system restore in Windows?', '**System Restore** is a Windows feature that allows users to **revert the computer''s system files and settings to a previous point in time**, without affecting personal files, useful for undoing problematic changes.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00138', 'computer-awareness-bank', 'Software & Operating Systems', 1, 65, 'What is the difference between software installation and software uninstallation?', '**Installation** is the process of **setting up software** on a computer so it can be used, copying necessary files and configuring settings.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00139', 'computer-awareness-bank', 'Software & Operating Systems', 1, 66, 'What is the purpose of a swap file / page file?', 'A **swap file** (or **page file**) is a reserved area on a **hard disk used as an extension of RAM**, where the operating system temporarily moves inactive data from memory to free up `RAM` for active processes, forming the basis of **virtual memory**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00140', 'computer-awareness-bank', 'Software & Operating Systems', 1, 67, 'What is containerization (e.g., Docker) and how does it differ from virtualization?', '**Containerization** packages an application with its dependencies into a lightweight **container** that shares the host operating system''s kernel, unlike **virtualization**, which runs full separate guest operating systems on virtual hardware via a hypervisor.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00141', 'computer-awareness-bank', 'Software & Operating Systems', 1, 68, 'What is open-source licensing exemplified by, such as the GNU GPL?', 'The `GNU` **General Public License (`GPL`)** is a widely used free software license that guarantees end users the **freedom to run, study, share, and modify** the software, and requires derivative works to be distributed under the same license terms.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00142', 'computer-awareness-bank', 'Software & Operating Systems', 1, 69, 'What is the significance of Unix in the history of operating systems?', '`Unix`, developed in the **late 1960s at Bell Labs**, was a pioneering multiuser, multitasking operating system that introduced concepts like the **hierarchical file system and the shell**, and directly influenced later systems including `Linux` and `macOS`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00143', 'computer-awareness-bank', 'Software & Operating Systems', 1, 70, 'What is the role of an operating system''s I/O management function?', '**Input/Output (`I/O`) management** in an operating system coordinates and controls **communication between the computer and peripheral devices**, handling data transfer requests from applications and managing device drivers.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00144', 'computer-awareness-bank', 'Software & Operating Systems', 1, 71, 'What is a firmware update, and why might it be needed?', 'A **firmware update** replaces or modifies the **low-level software embedded in a hardware device** (such as a router or `SSD`), typically to **fix bugs, improve performance, patch security vulnerabilities, or add new features**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00145', 'computer-awareness-bank', 'Internet & Networking', 2, 0, 'What does WWW stand for, and who is credited with inventing it?', '`WWW` stands for **World Wide Web**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00146', 'computer-awareness-bank', 'Internet & Networking', 2, 1, 'What is the difference between the Internet and the World Wide Web?', 'The **Internet** is the **global physical network infrastructure** of interconnected computers and devices.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00147', 'computer-awareness-bank', 'Internet & Networking', 2, 2, 'What does HTTP stand for, and what is its default port?', '`HTTP` stands for **HyperText Transfer Protocol**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00148', 'computer-awareness-bank', 'Internet & Networking', 2, 3, 'What does HTTPS stand for, and what is its default port?', '`HTTPS` stands for **HyperText Transfer Protocol Secure**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00149', 'computer-awareness-bank', 'Internet & Networking', 2, 4, 'What is the difference between HTTP and HTTPS?', '`HTTP` transmits data **in plain text**, making it vulnerable to interception.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00150', 'computer-awareness-bank', 'Internet & Networking', 2, 5, 'What does URL stand for?', '`URL` stands for **Uniform Resource Locator**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00151', 'computer-awareness-bank', 'Internet & Networking', 2, 6, 'What is an IP address?', 'An **IP (Internet Protocol) address** is a **unique numerical label** assigned to every device connected to a network, used to identify and locate the device for communication.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00152', 'computer-awareness-bank', 'Internet & Networking', 2, 7, 'What is the difference between IPv4 and IPv6?', '`IPv4` uses a **32-bit address** format (e.g., `192.168.1.1`), providing about **4.3 billion unique addresses**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00153', 'computer-awareness-bank', 'Internet & Networking', 2, 8, 'What is DNS, and what is its function?', '`DNS` stands for **Domain Name System**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00154', 'computer-awareness-bank', 'Internet & Networking', 2, 9, 'What port does DNS typically use?', '`DNS` (Domain Name System) typically uses **port `53`** for both queries and responses, over `UDP` for standard lookups and `TCP` for larger transfers like zone transfers.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00155', 'computer-awareness-bank', 'Internet & Networking', 2, 10, 'What does FTP stand for, and what are its default ports?', '`FTP` stands for **File Transfer Protocol**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00156', 'computer-awareness-bank', 'Internet & Networking', 2, 11, 'What does SMTP stand for, and what is it used for?', '`SMTP` stands for **Simple Mail Transfer Protocol**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00157', 'computer-awareness-bank', 'Internet & Networking', 2, 12, 'What is the difference between POP3 and IMAP for email retrieval?', '`POP3` (**Post Office Protocol version 3**) **downloads emails to a single device** and typically removes them from the server, using **port `110`**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00158', 'computer-awareness-bank', 'Internet & Networking', 2, 13, 'What does TCP/IP stand for?', '`TCP/IP` stands for **Transmission Control Protocol / Internet Protocol**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00159', 'computer-awareness-bank', 'Internet & Networking', 2, 14, 'What is the difference between TCP and UDP?', '`TCP` (**Transmission Control Protocol**) is **connection-oriented**, ensuring reliable, ordered delivery of data with error checking.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00160', 'computer-awareness-bank', 'Internet & Networking', 2, 15, 'What is a LAN?', '`LAN` stands for **Local Area Network**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00161', 'computer-awareness-bank', 'Internet & Networking', 2, 16, 'What is the difference between LAN, MAN, and WAN?', '`LAN` (**Local Area Network**) covers a small area like an office or building.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00162', 'computer-awareness-bank', 'Internet & Networking', 2, 17, 'What is a router?', 'A **router** is a networking device that **forwards data packets between different networks**, directing traffic based on `IP` addresses, and typically connects a local network to the internet.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00163', 'computer-awareness-bank', 'Internet & Networking', 2, 18, 'What is the difference between a hub, a switch, and a router?', 'A **hub** broadcasts incoming data to **all connected devices** regardless of the intended recipient.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00164', 'computer-awareness-bank', 'Internet & Networking', 2, 19, 'What is Wi-Fi, and which IEEE standard family defines it?', '**Wi-Fi** is a technology for **wireless local area networking**, allowing devices to connect to the internet without physical cables.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00165', 'computer-awareness-bank', 'Internet & Networking', 2, 20, 'What does Bluetooth technology enable, and over what typical range?', '**Bluetooth** is a **short-range wireless technology** used for exchanging data between fixed and mobile devices over short distances, typically up to about **10 meters**, commonly used for headsets, keyboards, and file transfers.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00166', 'computer-awareness-bank', 'Internet & Networking', 2, 21, 'What is the difference between Wi-Fi and Bluetooth?', '**Wi-Fi** is designed for **higher-speed, longer-range** wireless networking, typically used to connect to the internet.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00167', 'computer-awareness-bank', 'Internet & Networking', 2, 22, 'What is a firewall?', 'A **firewall** is a network security device or software that **monitors and controls incoming and outgoing network traffic** based on predetermined security rules, acting as a barrier between a trusted internal network and untrusted external networks.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00168', 'computer-awareness-bank', 'Internet & Networking', 2, 23, 'What is a proxy server?', 'A **proxy server** acts as an **intermediary between a client and the internet**, forwarding requests on the client''s behalf, which can provide benefits like anonymity, caching, and content filtering.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00169', 'computer-awareness-bank', 'Internet & Networking', 2, 24, 'What is VoIP?', '`VoIP` stands for **Voice over Internet Protocol**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00170', 'computer-awareness-bank', 'Internet & Networking', 2, 25, 'What is the OSI model, and how many layers does it have?', 'The `OSI` (**Open Systems Interconnection**) model is a **conceptual framework** that standardizes network communication functions into **seven layers**: Physical, Data Link, Network, Transport, Session, Presentation, and Application.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00171', 'computer-awareness-bank', 'Internet & Networking', 2, 26, 'Name the seven layers of the OSI model in order.', 'From bottom to top, the seven `OSI` layers are:
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00172', 'computer-awareness-bank', 'Internet & Networking', 2, 27, 'At which OSI layer does a router primarily operate?', 'A **router** primarily operates at the **Network layer (Layer 3)** of the `OSI` model, making forwarding decisions based on **IP addresses**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00173', 'computer-awareness-bank', 'Internet & Networking', 2, 28, 'At which OSI layer does a switch primarily operate?', 'A **switch** primarily operates at the **Data Link layer (Layer 2)** of the `OSI` model, forwarding frames based on **`MAC` addresses**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00174', 'computer-awareness-bank', 'Internet & Networking', 2, 29, 'What is bandwidth in networking?', '**Bandwidth** refers to the **maximum rate of data transfer** across a given network path, usually measured in **bits per second (`bps`)**, such as megabits per second (`Mbps`).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00175', 'computer-awareness-bank', 'Internet & Networking', 2, 30, 'What is the difference between upload speed and download speed?', '**Download speed** measures how fast data is **transferred from the internet to your device**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00176', 'computer-awareness-bank', 'Internet & Networking', 2, 31, 'What is a modem, in the context of internet connectivity?', 'A **modem** (**modulator-demodulator**) converts digital signals from a computer into **analog signals** suitable for transmission over telephone, cable, or fiber lines, and converts incoming analog signals back to digital data.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00177', 'computer-awareness-bank', 'Internet & Networking', 2, 32, 'What is broadband internet?', '**Broadband** refers to **high-speed internet access** that is always-on and significantly faster than traditional dial-up, typically delivered via technologies like `DSL`, cable, or fiber optics.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00178', 'computer-awareness-bank', 'Internet & Networking', 2, 33, 'What does DSL stand for?', '`DSL` stands for **Digital Subscriber Line**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00179', 'computer-awareness-bank', 'Internet & Networking', 2, 34, 'What is an email client? Give an example.', 'An **email client** is a software application used to **access and manage email messages** from a mail server.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00180', 'computer-awareness-bank', 'Internet & Networking', 2, 35, 'What is spam in the context of email?', '**Spam** refers to **unsolicited, often irrelevant or inappropriate bulk messages** sent over the internet, typically for advertising purposes, and is a common vector for phishing attacks.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00181', 'computer-awareness-bank', 'Internet & Networking', 2, 36, 'What does URL encoding/structure consist of (protocol, domain, path)?', 'A `URL` typically consists of a **protocol** (e.g., `https://`), a **domain name** (e.g., `www.example.com`), and a **path** to a specific resource (e.g., `/page.html`), along with optional query parameters.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00182', 'computer-awareness-bank', 'Internet & Networking', 2, 37, 'What is a domain name, and what is a Top-Level Domain (TLD)?', 'A **domain name** is the human-readable address of a website, such as `example.com`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00183', 'computer-awareness-bank', 'Internet & Networking', 2, 38, 'What is a web browser? Name three examples.', 'A **web browser** is a software application used to **access, retrieve, and display content** on the World Wide Web.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00184', 'computer-awareness-bank', 'Internet & Networking', 2, 39, 'What is a search engine? Name three examples.', 'A **search engine** is a software system designed to **search the World Wide Web for information** based on user queries, returning a list of relevant results.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00185', 'computer-awareness-bank', 'Internet & Networking', 2, 40, 'What is a cookie in the context of web browsing?', 'A **cookie** is a small piece of data stored by a **website on the user''s browser**, used to remember information such as login status, preferences, or shopping cart contents across sessions.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00186', 'computer-awareness-bank', 'Internet & Networking', 2, 41, 'What is a hyperlink?', 'A **hyperlink** is a **clickable reference** within a webpage that directs the user to another location — either a different section of the same page, another webpage, or a different website entirely.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00187', 'computer-awareness-bank', 'Internet & Networking', 2, 42, 'What is net neutrality?', '**Net neutrality** is the principle that **internet service providers must treat all data on the internet equally**, without discriminating or charging differently based on user, content, website, platform, or application.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00188', 'computer-awareness-bank', 'Internet & Networking', 2, 43, 'What is the function of a gateway in networking?', 'A **gateway** is a network node that serves as an **access point between two different networks** that use different protocols, often acting as the entry/exit point for traffic leaving a local network to the wider internet.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00189', 'computer-awareness-bank', 'Internet & Networking', 2, 44, 'What is a VPN, and why is it used?', '`VPN` stands for **Virtual Private Network**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00190', 'computer-awareness-bank', 'Internet & Networking', 2, 45, 'What is a packet in networking?', 'A **packet** is a **small unit of data** formatted for transmission over a network, containing both the actual data (payload) and control information (header) such as source and destination addresses.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00191', 'computer-awareness-bank', 'Internet & Networking', 2, 46, 'What is packet switching?', '**Packet switching** is a method of data transmission in which data is broken into small **packets**, each sent independently across a network and potentially via different routes, then reassembled at the destination.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00192', 'computer-awareness-bank', 'Internet & Networking', 2, 47, 'What does SSL/TLS stand for and what is its purpose?', '`SSL` (**Secure Sockets Layer**) and its successor `TLS` (**Transport Layer Security**) are cryptographic protocols that **encrypt data transmitted over a network**, ensuring secure communication between a client and server, forming the basis of `HTTPS`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00193', 'computer-awareness-bank', 'Internet & Networking', 2, 48, 'What is the function of a DHCP server?', '`DHCP` stands for **Dynamic Host Configuration Protocol**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00194', 'computer-awareness-bank', 'Internet & Networking', 2, 49, 'What is the difference between a static IP address and a dynamic IP address?', 'A **static IP address** is **manually assigned and remains fixed**, commonly used for servers.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00195', 'computer-awareness-bank', 'Internet & Networking', 2, 50, 'What is 4G and 5G in mobile networking?', '`4G` (**Fourth Generation**) and `5G` (**Fifth Generation**) refer to successive generations of **mobile network technology**, each offering progressively **higher data speeds, lower latency, and greater device capacity** compared to the previous generation.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00196', 'computer-awareness-bank', 'Internet & Networking', 2, 51, 'What is the purpose of a CAPTCHA?', 'A `CAPTCHA` (**Completely Automated Public Turing test to tell Computers and Humans Apart**) is a challenge-response test used on websites to **verify that a user is human** and not an automated bot, preventing spam and abuse.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00197', 'computer-awareness-bank', 'Internet & Networking', 2, 52, 'What is phishing?', '**Phishing** is a type of **cyberattack** where attackers send fraudulent messages, often disguised as being from a reputable source, to **trick victims into revealing sensitive information** like passwords or credit card numbers.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00198', 'computer-awareness-bank', 'Internet & Networking', 2, 53, 'What is a sitemap in web terminology?', 'A **sitemap** is a file that **lists the pages of a website**, helping search engines efficiently discover, crawl, and index its content.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00199', 'computer-awareness-bank', 'Internet & Networking', 2, 54, 'What is cloud storage? Give an example.', '**Cloud storage** allows users to **save data on remote servers** accessed via the internet, rather than on a local hard drive, enabling access from multiple devices.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00200', 'computer-awareness-bank', 'Internet & Networking', 2, 55, 'What is the function of a web server?', 'A **web server** is software (and the hardware it runs on) that **stores, processes, and delivers web pages to clients** upon request, typically using the `HTTP`/`HTTPS` protocol. Examples include `Apache` and `Nginx`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00201', 'computer-awareness-bank', 'Internet & Networking', 2, 56, 'What is a client-server model?', 'The **client-server model** is a network architecture where **clients (requesters)** send requests for resources or services to a **server (provider)**, which processes the requests and returns responses, such as a browser requesting a webpage from a web server.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00202', 'computer-awareness-bank', 'Internet & Networking', 2, 57, 'What is peer-to-peer (P2P) networking?', '**Peer-to-peer (`P2P`) networking** is a decentralized network model where **each computer (peer) can act as both a client and a server**, sharing resources directly with other peers without relying on a central server.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00203', 'computer-awareness-bank', 'Internet & Networking', 2, 58, 'What is Telnet, and what is its default port?', '`Telnet` is a network protocol used to provide **bidirectional, text-based remote terminal access** to another computer, using **port `23`**. It is considered insecure as data is transmitted in plain text, and has largely been replaced by `SSH`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00204', 'computer-awareness-bank', 'Internet & Networking', 2, 59, 'What is SSH, and what is its default port?', '`SSH` stands for **Secure Shell**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00205', 'computer-awareness-bank', 'Internet & Networking', 2, 60, 'What is the significance of ICANN?', '`ICANN` stands for **Internet Corporation for Assigned Names and Numbers**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00206', 'computer-awareness-bank', 'Internet & Networking', 2, 61, 'What is a subnet mask used for?', 'A **subnet mask** is used alongside an `IP` address to **distinguish the network portion from the host portion** of the address, enabling the division of a larger network into smaller sub-networks (subnets).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00207', 'computer-awareness-bank', 'Internet & Networking', 2, 62, 'What is the function of an access point in a wireless network?', 'A **wireless access point (`AP`)** is a networking device that allows **Wi-Fi-enabled devices to connect to a wired network**, extending wireless connectivity within a given area.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00208', 'computer-awareness-bank', 'Internet & Networking', 2, 63, 'What is latency in networking?', '**Latency** is the **time delay** between a user''s action (such as sending a request) and the response being received, usually measured in milliseconds (`ms`); lower latency indicates a more responsive connection.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00209', 'computer-awareness-bank', 'Internet & Networking', 2, 64, 'What is the function of a web cache?', 'A **web cache** temporarily **stores copies of web documents** (such as `HTML` pages and images) to reduce server load, bandwidth usage, and latency on subsequent requests for the same content.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00210', 'computer-awareness-bank', 'Internet & Networking', 2, 65, 'What does ISP stand for?', '`ISP` stands for **Internet Service Provider**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00211', 'computer-awareness-bank', 'Internet & Networking', 2, 66, 'What is the difference between intranet and extranet?', 'An **intranet** is a **private network restricted to an organization''s internal members**, used for internal communication and resource sharing.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00212', 'computer-awareness-bank', 'Internet & Networking', 2, 67, 'What is the Internet of Things (IoT)?', 'The **Internet of Things (`IoT`)** refers to a network of **physical devices embedded with sensors and software** that connect and exchange data over the internet, such as smart thermostats, wearable fitness trackers, and connected home appliances.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00213', 'computer-awareness-bank', 'Internet & Networking', 2, 68, 'What is a MAC address filter in a router?', '**`MAC` address filtering** is a security feature on routers that allows network administrators to **permit or deny network access to devices** based on their unique hardware (`MAC`) addresses.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00214', 'computer-awareness-bank', 'Internet & Networking', 2, 69, 'What is Net2 / 3G in the context of mobile network evolution (what does G stand for)?', 'In terms like `3G`, `4G`, and `5G`, **''G'' stands for Generation**, denoting successive advancements in **mobile telecommunications technology standards**, each offering improvements in speed, latency, and capacity.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00215', 'computer-awareness-bank', 'Internet & Networking', 2, 70, 'What is the significance of the term ''ping'' in networking?', '`ping` is a network utility used to **test the reachability of a host** on an `IP` network and measure the **round-trip time** for messages sent from the originating host to a destination and back.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00216', 'computer-awareness-bank', 'Internet & Networking', 2, 71, 'What does URL shortening accomplish, and give an example service?', '**URL shortening** converts a long web address into a **much shorter alias** that redirects to the original `URL`, making links easier to share.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00217', 'computer-awareness-bank', 'Database & MS Office', 3, 0, 'What is a database?', 'A **database** is an **organized collection of structured data** stored electronically, designed to be easily accessed, managed, and updated, typically through a **Database Management System (`DBMS`)**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00218', 'computer-awareness-bank', 'Database & MS Office', 3, 1, 'What does DBMS stand for?', '`DBMS` stands for **Database Management System**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00219', 'computer-awareness-bank', 'Database & MS Office', 3, 2, 'What is the difference between a DBMS and an RDBMS?', 'A `DBMS` (**Database Management System**) manages data generally, which may or may not be structured in tables.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00220', 'computer-awareness-bank', 'Database & MS Office', 3, 3, 'What is SQL, and what does it stand for?', '`SQL` stands for **Structured Query Language**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00221', 'computer-awareness-bank', 'Database & MS Office', 3, 4, 'What is a primary key in a database?', 'A **primary key** is a column (or set of columns) in a database table that **uniquely identifies each row/record**, and cannot contain `NULL` or duplicate values.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00222', 'computer-awareness-bank', 'Database & MS Office', 3, 5, 'What is a foreign key in a database?', 'A **foreign key** is a column in one table that **refers to the primary key of another table**, establishing and enforcing a **relationship (link)** between the two tables.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00223', 'computer-awareness-bank', 'Database & MS Office', 3, 6, 'What is normalization in database design?', '**Normalization** is the process of **organizing data in a database to reduce redundancy** and improve data integrity, typically by dividing large tables into smaller, related tables following a series of defined rules called **normal forms** (`1NF`, `2NF`, `3NF`, etc.).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00224', 'computer-awareness-bank', 'Database & MS Office', 3, 7, 'What is a table in a relational database?', 'A **table** is the basic structure in a relational database used to **store data in rows and columns**, where each **row** represents a record and each **column** represents a specific attribute or field.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00225', 'computer-awareness-bank', 'Database & MS Office', 3, 8, 'What is the difference between a row and a column in a database table?', 'A **row** (also called a **record** or **tuple**) represents a **single complete set of related data** in a table.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00226', 'computer-awareness-bank', 'Database & MS Office', 3, 9, 'What is a query in the context of databases?', 'A **query** is a **request for data or information** from a database, typically written in `SQL`, used to retrieve, filter, sort, or manipulate records stored in one or more tables.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00227', 'computer-awareness-bank', 'Database & MS Office', 3, 10, 'What does the SQL SELECT statement do?', 'The `SELECT` statement is used to **retrieve data from one or more tables** in a database.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00228', 'computer-awareness-bank', 'Database & MS Office', 3, 11, 'What is a JOIN operation in SQL?', 'A `JOIN` operation **combines rows from two or more tables** based on a related column between them.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00229', 'computer-awareness-bank', 'Database & MS Office', 3, 12, 'What is the difference between DELETE and DROP commands in SQL?', 'The `DELETE` command **removes specific rows** from a table based on a condition, while the **table structure remains intact**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00230', 'computer-awareness-bank', 'Database & MS Office', 3, 13, 'What is an index in a database, and why is it used?', 'An **index** is a data structure that **improves the speed of data retrieval** operations on a database table, functioning similarly to an index in a book, at the cost of additional storage and slower write operations.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00231', 'computer-awareness-bank', 'Database & MS Office', 3, 14, 'What is ACID in the context of database transactions?', '`ACID` stands for **Atomicity, Consistency, Isolation, and Durability**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00232', 'computer-awareness-bank', 'Database & MS Office', 3, 15, 'What is a NoSQL database? Give an example.', 'A **NoSQL database** is a type of database that provides a **non-relational, flexible-schema mechanism** for storing and retrieving data, unlike traditional table-based relational databases.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00233', 'computer-awareness-bank', 'Database & MS Office', 3, 16, 'What is a data warehouse?', 'A **data warehouse** is a **centralized repository** that stores large volumes of structured data from multiple sources, optimized for **reporting, analysis, and business intelligence** rather than day-to-day transaction processing.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00234', 'computer-awareness-bank', 'Database & MS Office', 3, 17, 'What is the difference between OLTP and OLAP?', '`OLTP` (**Online Transaction Processing**) handles **real-time, day-to-day transactional operations**, such as banking deposits or order entries.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00235', 'computer-awareness-bank', 'Database & MS Office', 3, 18, 'What is a backup in the context of database/data management?', 'A **backup** is a **copy of data stored separately** from the original, created to allow recovery in case of data loss, corruption, hardware failure, or accidental deletion.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00236', 'computer-awareness-bank', 'Database & MS Office', 3, 19, 'What is Microsoft Access used for?', '**Microsoft Access** is a **database management application** within the Microsoft Office suite that allows users to create, manage, and query relational databases using a graphical interface, combining the relational database engine with a GUI.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00237', 'computer-awareness-bank', 'Database & MS Office', 3, 20, 'What is Microsoft Word primarily used for?', '**Microsoft Word** is a **word processing application** used to create, edit, and format text documents, such as letters, reports, and resumes.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00238', 'computer-awareness-bank', 'Database & MS Office', 3, 21, 'What is the default file extension for a Microsoft Word document (modern format)?', 'The default file extension for a modern Microsoft Word document is **`.docx`**, based on the `XML`-based **Office Open XML** format introduced with Word 2007.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00239', 'computer-awareness-bank', 'Database & MS Office', 3, 22, 'What is Mail Merge in Microsoft Word used for?', '**Mail Merge** is a feature that allows users to **create multiple personalized documents** (such as letters or labels) by combining a **main document template** with a **data source** (like an Excel list of names and addresses).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00240', 'computer-awareness-bank', 'Database & MS Office', 3, 23, 'What is Microsoft Excel primarily used for?', '**Microsoft Excel** is a **spreadsheet application** used for organizing, calculating, analyzing, and visualizing data using rows, columns, formulas, and charts.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00241', 'computer-awareness-bank', 'Database & MS Office', 3, 24, 'What is a cell in Microsoft Excel?', 'A **cell** is the basic unit of a spreadsheet in Microsoft Excel, formed by the **intersection of a row and a column**, identified by a reference like `A1`, used to store text, numbers, or formulas.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00242', 'computer-awareness-bank', 'Database & MS Office', 3, 25, 'What is the function of the SUM formula in Excel?', 'The `SUM` function in Excel **adds together a range of numeric values**, for example `=SUM(A1:A10)` adds all values from cell `A1` through `A10`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00243', 'computer-awareness-bank', 'Database & MS Office', 3, 26, 'What is the function of the VLOOKUP formula in Excel?', 'The `VLOOKUP` (**Vertical Lookup**) function **searches for a value in the leftmost column of a table/range** and returns a corresponding value from a specified column in the same row.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00244', 'computer-awareness-bank', 'Database & MS Office', 3, 27, 'What is a pivot table in Microsoft Excel?', 'A **pivot table** is a data summarization tool in Excel that allows users to **automatically sort, count, total, or average data** stored in a spreadsheet, displaying the results in a new, reorganized table.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00245', 'computer-awareness-bank', 'Database & MS Office', 3, 28, 'What is the difference between a relative cell reference and an absolute cell reference in Excel?', 'A **relative cell reference** (e.g., `A1`) **changes automatically** when the formula is copied to another cell.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00246', 'computer-awareness-bank', 'Database & MS Office', 3, 29, 'What is conditional formatting in Excel?', '**Conditional formatting** is an Excel feature that **automatically applies formatting** (such as colors, icons, or data bars) to cells based on whether they meet **specified criteria**, making patterns and trends easier to visualize.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00247', 'computer-awareness-bank', 'Database & MS Office', 3, 30, 'What is Microsoft PowerPoint primarily used for?', '**Microsoft PowerPoint** is a **presentation software** used to create **slideshows** combining text, images, charts, and multimedia for presentations, lectures, and business pitches.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00248', 'computer-awareness-bank', 'Database & MS Office', 3, 31, 'What is a slide master in Microsoft PowerPoint?', 'A **slide master** is a feature in PowerPoint that controls the **overall design, layout, and formatting** applied consistently across all slides in a presentation, allowing changes to be made once and reflected throughout.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00249', 'computer-awareness-bank', 'Database & MS Office', 3, 32, 'What is the default file extension for a Microsoft Excel workbook (modern format)?', 'The default file extension for a modern Microsoft Excel workbook is **`.xlsx`**, based on the `XML`-based **Office Open XML** format.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00250', 'computer-awareness-bank', 'Database & MS Office', 3, 33, 'What is the default file extension for a Microsoft PowerPoint presentation (modern format)?', 'The default file extension for a modern Microsoft PowerPoint presentation is **`.pptx`**, based on the `XML`-based **Office Open XML** format.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00251', 'computer-awareness-bank', 'Database & MS Office', 3, 34, 'What is Microsoft Outlook primarily used for?', '**Microsoft Outlook** is a **personal information manager** used primarily as an **email client**, also offering calendar, task management, contact management, and note-taking features.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00252', 'computer-awareness-bank', 'Database & MS Office', 3, 35, 'What is a template in Microsoft Office applications?', 'A **template** is a **pre-formatted document** that serves as a starting point for creating new files, containing predefined styles, layouts, and placeholder content to save time and maintain consistency.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00253', 'computer-awareness-bank', 'Database & MS Office', 3, 36, 'What is Find and Replace used for in MS Office applications?', '**Find and Replace** is a feature that allows users to **search for specific text** within a document and **automatically substitute it** with different text, saving time on manual edits across large documents.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00254', 'computer-awareness-bank', 'Database & MS Office', 3, 37, 'What is the purpose of the ''Track Changes'' feature in Microsoft Word?', '**Track Changes** is a Word feature that **records edits made to a document**, such as insertions, deletions, and formatting changes, displaying them visibly so collaborators can review, accept, or reject each modification.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00255', 'computer-awareness-bank', 'Database & MS Office', 3, 38, 'What is a macro in Microsoft Office applications?', 'A **macro** is a **recorded or programmed sequence of actions/commands** that can be replayed to automate repetitive tasks in applications like Excel or Word, often written or edited using **`VBA`** (Visual Basic for Applications).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00256', 'computer-awareness-bank', 'Database & MS Office', 3, 39, 'What does VBA stand for?', '`VBA` stands for **Visual Basic for Applications**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00257', 'computer-awareness-bank', 'Database & MS Office', 3, 40, 'What is the function of the COUNTIF formula in Excel?', 'The `COUNTIF` function **counts the number of cells within a range that meet a specified condition**, for example `=COUNTIF(A1:A10,">50")` counts cells greater than 50.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00258', 'computer-awareness-bank', 'Database & MS Office', 3, 41, 'What is a chart in Microsoft Excel, and name one common type?', 'A **chart** is a visual representation of spreadsheet data, used to make **trends and comparisons easier to understand**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00259', 'computer-awareness-bank', 'Database & MS Office', 3, 42, 'What is freezing panes used for in Microsoft Excel?', '**Freeze Panes** is an Excel feature that **keeps specific rows or columns visible while scrolling** through the rest of the worksheet, commonly used to keep header rows in view on large datasets.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00260', 'computer-awareness-bank', 'Database & MS Office', 3, 43, 'What is the function of a header and footer in a document?', 'A **header** appears at the **top of every page** of a document, and a **footer** appears at the **bottom**, commonly used to display information like page numbers, titles, dates, or author names consistently throughout.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00261', 'computer-awareness-bank', 'Database & MS Office', 3, 44, 'What is the purpose of the IF formula in Excel?', 'The `IF` function performs a **logical test** and returns one value if the condition is `TRUE` and another if it is `FALSE`, for example `=IF(A1>50,"Pass","Fail")`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00262', 'computer-awareness-bank', 'Database & MS Office', 3, 45, 'What is a worksheet versus a workbook in Microsoft Excel?', 'A **worksheet** is a **single spreadsheet/tab** consisting of rows and columns.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00263', 'computer-awareness-bank', 'Database & MS Office', 3, 46, 'What is the Quick Access Toolbar in Microsoft Office applications?', 'The **Quick Access Toolbar** is a customizable toolbar located at the **top of the application window**, providing one-click access to frequently used commands such as Save, Undo, and Redo, independent of the active ribbon tab.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00264', 'computer-awareness-bank', 'Database & MS Office', 3, 47, 'What is the Ribbon in Microsoft Office applications?', 'The **Ribbon** is the **tabbed toolbar interface** at the top of Microsoft Office applications (introduced with Office 2007) that organizes commands into logical groups, replacing the older menu and toolbar system.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00265', 'computer-awareness-bank', 'Database & MS Office', 3, 48, 'What is a data type in the context of databases? Name three examples.', 'A **data type** defines the **kind of value a column can store** in a database table.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00266', 'computer-awareness-bank', 'Database & MS Office', 3, 49, 'What is a composite key in database design?', 'A **composite key** is a **combination of two or more columns** used together to uniquely identify a row in a table, used when no single column is sufficient to guarantee uniqueness on its own.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00267', 'computer-awareness-bank', 'Database & MS Office', 3, 50, 'What is the difference between a candidate key and a primary key?', 'A **candidate key** is any column (or set of columns) that **could qualify** as a unique identifier for a table''s rows.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00268', 'computer-awareness-bank', 'Database & MS Office', 3, 51, 'What is data redundancy, and why is it undesirable in databases?', '**Data redundancy** refers to the **unnecessary duplication of the same data** in multiple places within a database.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00269', 'computer-awareness-bank', 'Database & MS Office', 3, 52, 'What is a stored procedure in a database?', 'A **stored procedure** is a **precompiled collection of `SQL` statements** stored within the database itself, which can be executed repeatedly by calling its name, improving performance and code reuse.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00270', 'computer-awareness-bank', 'Database & MS Office', 3, 53, 'What is a schema in the context of a database?', 'A **schema** is the **logical structure or blueprint of a database**, defining how data is organized, including tables, fields, data types, and the relationships between them.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00271', 'computer-awareness-bank', 'Database & MS Office', 3, 54, 'What is a transaction in a database context?', 'A **transaction** is a **single logical unit of work** performed on a database, consisting of one or more operations, which must either **complete entirely or not at all** (atomicity) to maintain data integrity.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00272', 'computer-awareness-bank', 'Database & MS Office', 3, 55, 'What is the SQL WHERE clause used for?', 'The `WHERE` clause is used in `SQL` to **filter records**, specifying a condition that rows must satisfy to be included in the result of a `SELECT`, `UPDATE`, or `DELETE` statement.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00273', 'computer-awareness-bank', 'Database & MS Office', 3, 56, 'What is the purpose of the GROUP BY clause in SQL?', 'The `GROUP BY` clause **groups rows that share common values** in specified columns into summary rows, typically used alongside aggregate functions like `COUNT`, `SUM`, or `AVG`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00274', 'computer-awareness-bank', 'Database & MS Office', 3, 57, 'What is the difference between CHAR and VARCHAR data types in SQL?', '`CHAR` stores **fixed-length** character strings, padding shorter values with spaces to reach the defined length.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00275', 'computer-awareness-bank', 'Database & MS Office', 3, 58, 'What is database replication?', '**Database replication** is the process of **copying and maintaining database objects across multiple database servers**, used to improve data availability, fault tolerance, and read performance across geographically distributed systems.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00276', 'computer-awareness-bank', 'Database & MS Office', 3, 59, 'What is the purpose of an Entity-Relationship (ER) diagram?', 'An **Entity-Relationship (`ER`) diagram** is a visual representation used in database design to show **entities (tables), their attributes, and the relationships between them**, helping to plan the database structure before implementation.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00277', 'computer-awareness-bank', 'Database & MS Office', 3, 60, 'What is a view in a relational database?', 'A **view** is a **virtual table** based on the result of a stored `SQL` query, which does not store data itself but presents data from one or more underlying tables, often used to simplify complex queries or restrict access.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00278', 'computer-awareness-bank', 'Database & MS Office', 3, 61, 'What is the function of the ORDER BY clause in SQL?', 'The `ORDER BY` clause is used to **sort the result set** of a query in **ascending (`ASC`)** or **descending (`DESC`)** order, based on one or more specified columns.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00279', 'computer-awareness-bank', 'Database & MS Office', 3, 62, 'What does the UPDATE statement do in SQL?', 'The `UPDATE` statement is used to **modify existing records** in a table, typically combined with a `SET` clause to specify new values and a `WHERE` clause to target specific rows.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00280', 'computer-awareness-bank', 'Database & MS Office', 3, 63, 'What is a null value in a database?', 'A **null value** represents the **absence of any data value** in a field — it is distinct from zero or an empty string, indicating that the value is unknown, missing, or not applicable.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00281', 'computer-awareness-bank', 'Database & MS Office', 3, 64, 'What is the difference between Save and Save As in Microsoft Office applications?', '**Save** updates the **current file** at its existing location, overwriting the previous version.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00282', 'computer-awareness-bank', 'Database & MS Office', 3, 65, 'What is the purpose of spell check/grammar check in word processors?', '**Spell check and grammar check** are built-in tools in word processors that **automatically scan text for spelling errors and grammatical mistakes**, underlining issues and suggesting corrections to improve document accuracy.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00283', 'computer-awareness-bank', 'Database & MS Office', 3, 66, 'What is the function of the AutoSum button in Microsoft Excel?', 'The **AutoSum** button is a quick-access feature in Excel that automatically **inserts a `SUM` (or other common aggregate) formula** for a selected range of adjacent cells, without the user having to type the formula manually.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00284', 'computer-awareness-bank', 'Database & MS Office', 3, 67, 'What is a filter in Microsoft Excel used for?', 'A **filter** in Excel allows users to **display only rows that meet specific criteria**, temporarily hiding the rows that do not match, making it easier to analyze specific subsets of large datasets.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00285', 'computer-awareness-bank', 'Database & MS Office', 3, 68, 'What does CSV stand for, and what is it used for?', '`CSV` stands for **Comma-Separated Values**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00286', 'computer-awareness-bank', 'Database & MS Office', 3, 69, 'What is Big Data, and what are its commonly cited characteristics (the ''V''s)?', '**Big Data** refers to **extremely large and complex data sets** that traditional data processing software cannot adequately handle.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00287', 'computer-awareness-bank', 'Database & MS Office', 3, 70, 'What is data mining?', '**Data mining** is the process of **discovering patterns, correlations, and useful insights** from large sets of data, using techniques from statistics, machine learning, and database systems.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00288', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 0, 'What is a computer virus?', 'A **computer virus** is a type of **malicious software (malware)** that attaches itself to a legitimate program or file and **replicates itself** when executed, often damaging data or disrupting system operations.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00289', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 1, 'What is the difference between a computer virus and a worm?', 'A **virus** requires a **host program or file** to attach to, and needs human action (like opening a file) to spread.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00290', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 2, 'What is a Trojan horse in computing?', 'A **Trojan horse** is a type of **malware disguised as legitimate or useful software**, which, once installed, can give attackers unauthorized access to the system, unlike a virus, it does not self-replicate.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00291', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 3, 'What is ransomware?', '**Ransomware** is a type of malicious software that **encrypts a victim''s files or locks them out of their system**, with the attacker demanding a **ransom payment** in exchange for restoring access.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00292', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 4, 'What is spyware?', '**Spyware** is malicious software designed to **secretly monitor and collect information** about a user''s activities, such as browsing habits, keystrokes, or personal data, without their knowledge or consent.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00293', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 5, 'What is adware?', '**Adware** is software that **automatically displays or downloads unwanted advertisements**, often bundled with free software, and can sometimes track user behavior to serve targeted ads.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00294', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 6, 'What is a keylogger?', 'A **keylogger** is a type of surveillance software or hardware device that **records every keystroke made on a device**, often used maliciously to steal passwords and sensitive information.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00295', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 7, 'What is phishing, and how does it typically work?', '**Phishing** is a social engineering attack where attackers send **fraudulent emails or messages** disguised as being from a trusted source, tricking victims into **revealing sensitive information** like passwords or clicking malicious links.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00296', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 8, 'What is spear phishing?', '**Spear phishing** is a **targeted form of phishing** aimed at a specific individual, organization, or business, using personalized information to make the fraudulent message more convincing than generic phishing attempts.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00297', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 9, 'What is malware? Name three types.', '**Malware** (malicious software) is any software **intentionally designed to cause damage** to a computer, server, or network.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00298', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 10, 'What is a firewall, and how does it enhance security?', 'A **firewall** is a network security system that **monitors and controls incoming and outgoing traffic** based on predefined security rules, acting as a barrier between a trusted internal network and untrusted external sources like the internet.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00299', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 11, 'What is two-factor authentication (2FA)?', '**Two-factor authentication (`2FA`)** is a security process that requires users to provide **two different forms of identification** to verify their identity — typically something they know (a password) and something they have (an `OTP` or authentication app).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00300', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 12, 'What is encryption?', '**Encryption** is the process of **converting readable data (plaintext) into an unreadable coded format (ciphertext)** using an algorithm and a key, protecting the information from unauthorized access during storage or transmission.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00301', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 13, 'What is the difference between symmetric and asymmetric encryption?', '**Symmetric encryption** uses the **same single key** for both encrypting and decrypting data, making it faster but requiring secure key sharing.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00302', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 14, 'What is a password manager?', 'A **password manager** is a software application that **securely stores and manages passwords** for various accounts in an encrypted vault, allowing users to generate and use strong, unique passwords without needing to memorize each one.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00303', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 15, 'What is a brute-force attack?', 'A **brute-force attack** is a hacking method that uses **trial-and-error to systematically guess passwords or encryption keys**, attempting every possible combination until the correct one is found.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00304', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 16, 'What is a Denial-of-Service (DoS) attack?', 'A **Denial-of-Service (`DoS`) attack** attempts to **make a system, service, or network unavailable to its intended users**, typically by overwhelming it with excessive traffic or requests.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00305', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 17, 'What is the difference between a DoS attack and a DDoS attack?', 'A `DoS` (**Denial-of-Service**) attack originates from a **single source** flooding a target with traffic.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00306', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 18, 'What is a botnet?', 'A **botnet** is a **network of internet-connected devices infected with malware** and controlled remotely by an attacker, often used to carry out large-scale attacks like `DDoS`, spam campaigns, or data theft, without the device owners'' knowledge.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00307', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 19, 'What is social engineering in the context of cybersecurity?', '**Social engineering** is the use of **psychological manipulation to trick people** into divulging confidential information or performing actions that compromise security, rather than exploiting purely technical vulnerabilities.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00308', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 20, 'What is spoofing in cybersecurity?', '**Spoofing** is a technique where an attacker **disguises their identity or communication source** to appear as a trusted entity, such as faking an email sender address or an `IP` address, in order to deceive a victim.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00309', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 21, 'What is a man-in-the-middle (MITM) attack?', 'A **Man-in-the-Middle (`MITM`) attack** occurs when an attacker **secretly intercepts and potentially alters communication** between two parties who believe they are communicating directly with each other.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00310', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 22, 'What is a zero-day vulnerability?', 'A **zero-day vulnerability** is a **security flaw in software that is unknown to the vendor** (and thus has ''zero days'' of available patch), making it particularly dangerous as attackers can exploit it before a fix is released.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00311', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 23, 'What does CAPTCHA protect against?', 'A `CAPTCHA` helps protect websites against **automated bot attacks**, such as spam submissions, credential stuffing, and fraudulent account creation, by requiring a test that is easy for humans but difficult for automated scripts to pass.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00312', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 24, 'What is an antivirus program''s primary function?', 'An **antivirus program** is designed to **detect, quarantine, and remove malicious software** from a computer system, typically using signature-based detection and behavioral/heuristic analysis to identify threats.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00313', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 25, 'What is a digital signature?', 'A **digital signature** is a **cryptographic mechanism** used to verify the **authenticity and integrity** of a digital message or document, ensuring it was created by a known sender and has not been altered since signing.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00314', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 26, 'What is a Certificate Authority (CA)?', 'A **Certificate Authority (`CA`)** is a trusted organization that **issues digital certificates**, verifying the identity of websites, individuals, or organizations, forming the basis of trust used in `HTTPS`/`SSL`/`TLS` connections.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00315', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 27, 'What is the significance of the padlock icon in a web browser?', 'The **padlock icon** in a browser''s address bar indicates that the connection to the website is **secured using `HTTPS`/`TLS` encryption**, meaning data exchanged between the browser and server is encrypted.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00316', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 28, 'What is data breach, and what can it expose?', 'A **data breach** is an incident in which **confidential or protected information is accessed, disclosed, or stolen without authorization**, potentially exposing personal data, financial records, or trade secrets.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00317', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 29, 'What is identity theft?', '**Identity theft** is a crime where someone **illegally obtains and uses another person''s personal information** (such as Aadhaar, PAN, or bank details), typically for financial gain or fraud.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00318', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 30, 'What is a VPN, and how does it help with cybersecurity?', 'A `VPN` (**Virtual Private Network**) creates an **encrypted tunnel** for internet traffic, masking the user''s `IP` address and protecting data from being intercepted on public or untrusted networks.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00319', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 31, 'What is patch management in cybersecurity?', '**Patch management** is the process of **regularly updating software and systems** with the latest security patches and fixes, reducing the risk of exploitation through known vulnerabilities.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00320', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 32, 'What is the purpose of a honeypot in cybersecurity?', 'A **honeypot** is a **decoy system or network** deliberately set up to attract and detect attackers, allowing security teams to **study attack methods** and divert attention away from real, valuable targets.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00321', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 33, 'What is a rootkit?', 'A **rootkit** is a type of malicious software designed to **gain unauthorized root/administrator-level access** to a system while **hiding its presence** from the user and standard detection tools.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00322', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 34, 'What is a logic bomb?', 'A **logic bomb** is a piece of malicious code **intentionally inserted into software that lies dormant until triggered** by a specific condition or date, at which point it executes a harmful action.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00323', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 35, 'What is the CIA triad in information security?', 'The `CIA` triad refers to the three core principles of information security:
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00324', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 36, 'What is biometric authentication?', '**Biometric authentication** verifies a person''s identity using **unique physical or behavioral characteristics**, such as fingerprints, facial recognition, or iris scans, rather than relying solely on passwords.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00325', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 37, 'What is the difference between hacking and ethical hacking?', '**Hacking** generally refers to **unauthorized access** to computer systems, often with malicious intent.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00326', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 38, 'What does the term ''white hat'' hacker mean?', 'A **white hat hacker** is an **ethical security professional** who uses hacking skills **legally and with authorization** to identify and fix vulnerabilities in systems, helping to improve overall security.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00327', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 39, 'What does the term ''black hat'' hacker mean?', 'A **black hat hacker** is someone who engages in **unauthorized, malicious hacking** for personal gain, to cause damage, or for other illegal purposes, exploiting system vulnerabilities without permission.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00328', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 40, 'What is a ''grey hat'' hacker?', 'A **grey hat hacker** operates **between ethical and malicious hacking** — they may find and exploit vulnerabilities without authorization, but typically without malicious intent, sometimes later disclosing the flaw to the organization.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00329', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 41, 'What is SQL injection?', '`SQL injection` is a code injection technique where an attacker **inserts malicious `SQL` statements into an input field**, exploiting vulnerabilities in an application''s database layer to access, modify, or delete data without authorization.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00330', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 42, 'What is cross-site scripting (XSS)?', '`XSS` (**Cross-Site Scripting**) is a web security vulnerability that allows attackers to **inject malicious scripts into web pages** viewed by other users, potentially stealing session data or redirecting users to malicious sites.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00331', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 43, 'What is a security patch?', 'A **security patch** is an **update released by a software vendor** specifically to fix a known security vulnerability, helping to protect systems from being exploited by attackers.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00332', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 44, 'What is the purpose of data backup in cybersecurity strategy?', '**Data backup** involves creating and storing **copies of important data separately** from the original source, enabling recovery in the event of a ransomware attack, hardware failure, or accidental deletion.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00333', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 45, 'What is multi-factor authentication (MFA)?', '**Multi-Factor Authentication (`MFA`)** requires users to verify their identity using **two or more independent credentials**, such as a password, a one-time code, and a biometric scan, significantly strengthening account security beyond `2FA`''s minimum of two factors.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00334', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 46, 'What is an OTP, and how is it used in security?', '`OTP` stands for **One-Time Password**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00335', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 47, 'What is pharming in cybersecurity?', '**Pharming** is a cyberattack that **redirects users from a legitimate website to a fraudulent one**, typically by exploiting `DNS` vulnerabilities, without requiring the victim to click a malicious link as in traditional phishing.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00336', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 48, 'What is a security audit?', 'A **security audit** is a **systematic evaluation** of an organization''s information systems, policies, and controls to assess their **effectiveness in protecting against security threats** and compliance with relevant standards.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00337', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 49, 'What is the India-specific cybersecurity law commonly referenced for IT offenses?', 'The **Information Technology Act, 2000** (`IT Act`) is the primary law in India governing **cybercrime and electronic commerce**, covering offenses like hacking, data theft, and cyber fraud.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00338', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 50, 'What is CERT-In in the context of India''s cybersecurity?', '`CERT-In` stands for the **Indian Computer Emergency Response Team**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00339', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 51, 'What is a digital certificate used for?', 'A **digital certificate** is an electronic credential issued by a **Certificate Authority (`CA`)** that verifies the identity of a website, server, or individual, and is used to establish secure, encrypted connections such as `HTTPS`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00340', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 52, 'What is the principle of least privilege in cybersecurity?', 'The **principle of least privilege** states that **users and systems should be granted only the minimum levels of access** necessary to perform their required functions, reducing the potential impact of a compromised account.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00341', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 53, 'What is a security token (hardware or software)?', 'A **security token** is a physical device or software application that **generates or stores authentication credentials**, such as one-time codes, used as an additional factor to verify a user''s identity during login.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00342', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 54, 'What is cyberbullying?', '**Cyberbullying** is the use of **digital technology, such as social media, messaging apps, or online platforms, to harass, threaten, or intimidate** another individual, often targeting minors.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00343', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 55, 'What is data integrity in the context of cybersecurity?', '**Data integrity** refers to the **accuracy, consistency, and trustworthiness of data** over its entire lifecycle, ensuring it has not been altered or corrupted, whether accidentally or maliciously.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00344', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 56, 'What is a firewall rule, in simple terms?', 'A **firewall rule** is a specific **instruction that determines whether to allow or block network traffic** based on criteria such as source/destination `IP` address, port number, or protocol type.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00345', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 57, 'What is the purpose of a VPN kill switch?', 'A **VPN kill switch** is a security feature that **automatically disconnects a device from the internet** if the `VPN` connection drops unexpectedly, preventing data from being transmitted outside the secure, encrypted tunnel.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00346', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 58, 'What is drive-by download in cybersecurity?', 'A **drive-by download** is the **unintentional download of malicious software** onto a device, often occurring simply by visiting a compromised or malicious website, without the user clicking anything or granting explicit permission.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00347', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 59, 'What is the purpose of access control lists (ACLs) in network security?', 'An **Access Control List (`ACL`)** is a set of rules used by routers and firewalls to **control which users, devices, or traffic are permitted or denied access** to specific network resources.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00348', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 60, 'What is the term for malware that specifically targets mobile devices?', '**Mobile malware** refers to malicious software **specifically designed to target smartphones and tablets**, often disguised as legitimate apps, capable of stealing data, tracking location, or sending premium-rate messages without consent.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00349', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 61, 'What is the significance of regularly updating software for cybersecurity?', 'Regularly updating software ensures that **known security vulnerabilities are patched promptly**, reducing the window of opportunity for attackers to exploit outdated code before a fix is applied.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00350', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 62, 'What is a session hijacking attack?', '**Session hijacking** is an attack where a malicious actor **takes over a valid user''s active session** (often by stealing a session token or cookie), gaining unauthorized access to a web application as if they were the legitimate user.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00351', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 63, 'What is a watering hole attack?', 'A **watering hole attack** involves attackers **compromising a website that a specific target group frequently visits**, infecting it with malware, so that visiting members of the group become infected without being directly targeted individually.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00352', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 64, 'What is the function of antivirus signature updates?', '**Signature updates** provide an antivirus program with the **latest definitions of known malware**, allowing it to recognize and block newly discovered threats that were not present in previous versions of its database.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00353', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 65, 'What is cryptojacking?', '**Cryptojacking** is the **unauthorized use of someone else''s computing resources** to mine cryptocurrency, typically carried out through malware or malicious scripts embedded in websites, without the victim''s knowledge or consent.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00354', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 66, 'What is the purpose of a Virtual Private Network''s encryption protocol, such as OpenVPN?', 'A `VPN` encryption protocol, such as `OpenVPN` or `WireGuard`, defines the **rules and methods used to establish and secure the encrypted tunnel** between a device and the VPN server, balancing security strength with connection speed.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00355', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 67, 'What is data loss prevention (DLP)?', '**Data Loss Prevention (`DLP`)** refers to a set of tools and strategies used to **ensure sensitive data is not lost, misused, or accessed by unauthorized users**, often by monitoring and controlling data transfer across a network.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00356', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 68, 'What is the purpose of an intrusion detection system (IDS)?', 'An **Intrusion Detection System (`IDS`)** monitors network or system activity for **malicious actions or policy violations**, alerting administrators when suspicious behavior is detected, without necessarily blocking the traffic itself.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00357', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 69, 'What is the difference between an IDS and an IPS?', 'An `IDS` (**Intrusion Detection System**) **monitors and alerts** on suspicious activity without taking direct action.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00358', 'computer-awareness-bank', 'Cybersecurity Basics', 4, 70, 'What is the purpose of safe browsing habits like checking a URL before clicking?', 'Checking a `URL` before clicking helps users **identify fraudulent or spoofed websites** that mimic legitimate ones, a common tactic in phishing attacks, by spotting misspellings or suspicious domain names before entering sensitive information.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00359', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 0, 'What is a programming language?', 'A **programming language** is a **formal set of instructions and syntax** used to write computer programs, enabling humans to communicate instructions that a computer can execute, such as `Python`, `Java`, or `C++`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00360', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 1, 'What is the difference between a high-level and a low-level programming language?', 'A **high-level language** (like `Python` or `Java`) uses **human-readable syntax** abstracted away from hardware details, making it easier to write and maintain.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00361', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 2, 'What is an algorithm?', 'An **algorithm** is a **finite, well-defined sequence of steps or instructions** designed to solve a specific problem or perform a computation, independent of any particular programming language.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00362', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 3, 'What is a flowchart?', 'A **flowchart** is a **diagrammatic representation of an algorithm or process**, using standardized symbols (like ovals, rectangles, and diamonds) to show the sequence of steps and decision points.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00363', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 4, 'What is the difference between source code and object code?', '**Source code** is the **human-readable program** written by a programmer in a high-level language.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00364', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 5, 'What is a variable in programming?', 'A **variable** is a **named storage location in memory** used to hold a value that can change during the execution of a program, identified by a name and associated with a specific data type.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00365', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 6, 'What is a loop in programming?', 'A **loop** is a programming construct that **repeats a block of code multiple times**, until a specified condition is met, commonly implemented using structures like `for`, `while`, or `do-while`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00366', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 7, 'What is a function (or subroutine) in programming?', 'A **function** (or subroutine) is a **reusable, self-contained block of code** designed to perform a specific task, which can be called multiple times within a program, often accepting inputs (parameters) and returning an output.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00367', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 8, 'What is an array in programming?', 'An **array** is a **data structure that stores a fixed-size collection of elements**, typically of the same data type, accessed using an **index**, allowing efficient storage and retrieval of multiple related values.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00368', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 9, 'What is object-oriented programming (OOP)?', '**Object-Oriented Programming (`OOP`)** is a programming paradigm based on the concept of **''objects''**, which bundle data (attributes) and behavior (methods) together, built around principles like **encapsulation, inheritance, and polymorphism**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00369', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 10, 'What are the four main principles of object-oriented programming?', 'The four main principles of `OOP` are:
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00370', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 11, 'What is a class in object-oriented programming?', 'A **class** is a **blueprint or template** for creating objects, defining the properties (attributes) and behaviors (methods) that its objects will have.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00371', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 12, 'What is an object in object-oriented programming?', 'An **object** is a **specific instance of a class**, containing actual values for the attributes defined by that class, along with access to the class''s methods.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00372', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 13, 'What is inheritance in object-oriented programming?', '**Inheritance** is an `OOP` principle that allows a **new class (subclass/child) to acquire the properties and methods of an existing class (superclass/parent)**, promoting code reuse and establishing a hierarchical relationship.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00373', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 14, 'What is polymorphism in object-oriented programming?', '**Polymorphism** is an `OOP` principle that allows **objects of different classes to be treated as objects of a common superclass**, enabling a single function or method name to behave differently depending on the object calling it.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00374', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 15, 'What is encapsulation in object-oriented programming?', '**Encapsulation** is the `OOP` principle of **bundling data and the methods that operate on it within a single unit (class)**, while restricting direct access to some of the object''s internal components, typically through access modifiers.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00375', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 16, 'What is debugging in software development?', '**Debugging** is the process of **identifying, analyzing, and fixing errors or bugs** within a computer program''s source code to ensure it runs correctly.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00376', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 17, 'What is pseudocode?', '**Pseudocode** is an **informal, high-level description of a program''s logic**, written in a mix of natural language and simplified programming structure, used to plan an algorithm before writing actual code.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00377', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 18, 'What is syntax error versus logical error in programming?', 'A **syntax error** occurs when code **violates the grammatical rules** of the programming language, preventing it from compiling or running.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00378', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 19, 'What does IDE stand for?', '`IDE` stands for **Integrated Development Environment**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00379', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 20, 'What does HTML stand for?', '`HTML` stands for **HyperText Markup Language**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00380', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 21, 'What does CSS stand for, and what is its purpose?', '`CSS` stands for **Cascading Style Sheets**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00381', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 22, 'What is JavaScript, and what is it primarily used for?', '**JavaScript** is a **high-level programming language** primarily used to add **interactivity and dynamic behavior** to web pages, running in the user''s browser as a client-side scripting language, though it is also widely used server-side (e.g., `Node.js`).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00382', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 23, 'What does XML stand for?', '`XML` stands for **Extensible Markup Language**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00383', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 24, 'What does JSON stand for?', '`JSON` stands for **JavaScript Object Notation**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00384', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 25, 'What does COBOL stand for?', '`COBOL` stands for **Common Business-Oriented Language**, one of the earliest high-level programming languages, designed in **1959** for business, finance, and administrative data processing.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00385', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 26, 'What does FORTRAN stand for?', '`FORTRAN` stands for **Formula Translation**, one of the earliest high-level programming languages, developed by `IBM` in the **1950s** primarily for scientific and engineering numerical computation.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00386', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 27, 'What does BASIC stand for?', '`BASIC` stands for **Beginner''s All-purpose Symbolic Instruction Code**, a programming language designed in the 1960s to be **simple to learn**, making computing accessible to non-specialists.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00387', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 28, 'What does WYSIWYG stand for?', '`WYSIWYG` stands for **What You See Is What You Get**, describing editing software (such as word processors) where the **on-screen display matches the final printed or published output**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00388', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 29, 'What does GIGO mean in computing?', '`GIGO` stands for **Garbage In, Garbage Out**, a computing principle meaning that **flawed or poor-quality input data will produce flawed or poor-quality output**, regardless of how correct the processing logic is.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00389', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 30, 'What does ALGOL stand for?', '`ALGOL` stands for **Algorithmic Language**, an influential high-level programming language from the late 1950s whose block structure and syntax **influenced many later languages**, including `C` and `Pascal`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00390', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 31, 'What does RISC stand for in processor design?', '`RISC` stands for **Reduced Instruction Set Computer**, a processor design philosophy that uses a **small, highly optimized set of simple instructions**, aiming for faster execution per instruction, in contrast to `CISC` (Complex Instruction Set Computer) designs.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00391', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 32, 'What does PDF stand for?', '`PDF` stands for **Portable Document Format**, a file format developed by Adobe that preserves document formatting across different devices and operating systems.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00392', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 33, 'What does GIF stand for?', '`GIF` stands for **Graphics Interchange Format**, a bitmap image format that supports both static images and simple animations, commonly used on the web.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00393', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 34, 'What does JPEG stand for?', '`JPEG` stands for **Joint Photographic Experts Group**, a widely used method of lossy compression for digital photographic images.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00394', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 35, 'What does PNG stand for?', '`PNG` stands for **Portable Network Graphics**, a raster image format that uses lossless compression and supports transparency, commonly used for web graphics.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00395', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 36, 'What does ASCII stand for?', '`ASCII` stands for **American Standard Code for Information Interchange**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00396', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 37, 'What does Unicode represent, and why was it developed?', '**Unicode** is a universal character encoding standard designed to represent **text from virtually all writing systems in the world** consistently, overcoming the limitations of older encodings like `ASCII` that could not represent non-English scripts.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00397', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 38, 'What does CAD stand for?', '`CAD` stands for **Computer-Aided Design**, software used by engineers, architects, and designers to **create precise 2D drawings and 3D models** of products, buildings, or components.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00398', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 39, 'What does CAM stand for, alongside CAD?', '`CAM` stands for **Computer-Aided Manufacturing**, software that uses the design data from `CAD` to **control and automate manufacturing machinery**, such as `CNC` machines, during production.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00399', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 40, 'What does DTP stand for?', '`DTP` stands for **Desktop Publishing**, the use of computer software to **design and lay out documents** such as newsletters, brochures, and books, combining text and graphics for print or digital publication.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00400', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 41, 'What does WAP stand for?', '`WAP` stands for **Wireless Application Protocol**, a technical standard that enabled **early mobile phones with limited processing power to access simplified internet content** before the rise of modern smartphone browsers.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00401', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 42, 'What does AI stand for, and what does it refer to?', '`AI` stands for **Artificial Intelligence**, referring to the **simulation of human intelligence processes** by computer systems, including learning, reasoning, and self-correction.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00402', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 43, 'What does ML stand for, in the context of AI?', '`ML` stands for **Machine Learning**, a subset of `AI` where systems **learn patterns from data** to make predictions or decisions, without being explicitly programmed for each specific task.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00403', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 44, 'What does AR stand for, and how does it differ from VR?', '`AR` stands for **Augmented Reality**, which **overlays digital content onto the real world** (viewed through a camera or glasses), unlike `VR` (**Virtual Reality**), which immerses the user in a **completely simulated digital environment**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00404', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 45, 'What does ERP stand for?', '`ERP` stands for **Enterprise Resource Planning**, integrated software used by organizations to **manage core business processes** such as finance, HR, supply chain, and manufacturing in a unified system.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00405', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 46, 'What does CRM stand for?', '`CRM` stands for **Customer Relationship Management**, software used by organizations to **manage interactions with current and potential customers**, including sales, service, and marketing data.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00406', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 47, 'What does GPS stand for?', '`GPS` stands for **Global Positioning System**, a satellite-based navigation system that provides **location and time information** anywhere on or near the Earth''s surface.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00407', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 48, 'What does ATM stand for in banking technology?', '`ATM` stands for **Automated Teller Machine**, an electronic banking device that allows customers to **perform basic transactions**, such as cash withdrawal and balance inquiry, without needing a bank teller.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00408', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 49, 'What does POS stand for in retail/banking technology?', '`POS` stands for **Point of Sale**, referring to the **place and system where a retail transaction is completed**, typically involving a terminal that processes card or digital payments.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00409', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 50, 'What does EMI stand for in finance-technology context?', '`EMI` stands for **Equated Monthly Installment**, a fixed payment amount made by a borrower to a lender on a specified date each month, used to repay loans over time.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00410', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 51, 'What does PIN stand for?', '`PIN` stands for **Personal Identification Number**, a numeric code used to authenticate a user''s identity, commonly for `ATM` transactions, card payments, and device unlocking.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00411', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 52, 'What does WPA stand for in wireless security?', '`WPA` stands for **Wi-Fi Protected Access**, a security protocol designed to **secure wireless computer networks**, succeeding the older and less secure `WEP` (Wired Equivalent Privacy) standard.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00412', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 53, 'What does URL redirection commonly relate to the abbreviation HTTP status code 404?', '`HTTP` status code `404` means **''Not Found''**, indicating the server could not locate the requested resource, while other common codes include `200` (**OK/success**) and `500` (**Internal Server Error**).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00413', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 54, 'What does XaaS stand for?', '`XaaS` stands for **Anything as a Service** (or Everything as a Service), an umbrella term covering **cloud-delivered service models** such as `SaaS`, `PaaS`, and `IaaS`, where capabilities are provided over the internet rather than owned locally.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00414', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 55, 'What does FAQ stand for?', '`FAQ` stands for **Frequently Asked Questions**, a list format used to present common questions and their answers, typically found on websites to help users quickly find information.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00415', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 56, 'What does SMS stand for?', '`SMS` stands for **Short Message Service**, a text messaging service that allows the exchange of short text messages between mobile phones over cellular networks.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00416', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 57, 'What does IMEI stand for?', '`IMEI` stands for **International Mobile Equipment Identity**, a unique 15-digit number assigned to every mobile phone, used to identify the device on a mobile network.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00417', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 58, 'What does SIM stand for?', '`SIM` stands for **Subscriber Identity Module**, a small smart card inserted into a mobile phone that stores data to authenticate a subscriber on a cellular network.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00418', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 59, 'What does EDGE stand for in mobile telecommunications?', '`EDGE` stands for **Enhanced Data rates for GSM Evolution**, a mobile data technology that provided faster data transmission than earlier `2G` `GPRS` networks, often described as `2.75G`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00419', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 60, 'What does CDMA stand for?', '`CDMA` stands for **Code Division Multiple Access**, a channel access method used in mobile telecommunications that allows multiple signals to share the same frequency band by assigning unique codes to each transmission.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00420', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 61, 'What does GSM stand for?', '`GSM` stands for **Global System for Mobile Communications**, a widely adopted digital standard for mobile telecommunications used across most of the world.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00421', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 62, 'What does WORM stand for in the context of storage media?', 'In storage contexts, `WORM` stands for **Write Once Read Many**, referring to storage media that can be written to **only a single time** but read an unlimited number of times afterward, often used for archival records.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00422', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 63, 'What does EOF stand for in programming?', '`EOF` stands for **End Of File**, a condition or marker indicating that there is **no more data to be read** from a file or input stream.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00423', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 64, 'What is the difference between a compiler error and a runtime error?', 'A **compiler error** occurs **before the program runs**, typically due to a syntax violation that prevents the code from being translated into executable form.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00424', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 65, 'What is version control, and name one common tool?', '**Version control** is a system that **records changes to files over time**, allowing developers to track history, revert to previous versions, and collaborate without overwriting each other''s work.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00425', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 66, 'What is open-source software in the programming context, and give an example of an open-source programming language?', '**Open-source software** has its **source code publicly available** for anyone to view, use, modify, and distribute.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00426', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 67, 'What is a conditional statement in programming (e.g., if-else)?', 'A **conditional statement**, such as `if-else`, allows a program to **execute different blocks of code depending on whether a specified condition evaluates to true or false**, enabling decision-making logic.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00427', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 68, 'What is recursion in programming?', '**Recursion** is a programming technique in which a **function calls itself** in order to solve a problem by breaking it down into smaller, similar sub-problems, continuing until a defined base case is reached.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00428', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 69, 'What is the difference between a stack and a queue data structure?', 'A **stack** follows the **`LIFO` (Last In, First Out)** principle, where the most recently added element is removed first.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00429', 'computer-awareness-bank', 'Programming Concepts & Abbreviations', 5, 70, 'What does SDK stand for?', '`SDK` stands for **Software Development Kit**, a collection of tools, libraries, and documentation that developers use to **build applications for a specific platform or framework**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00430', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 0, 'Who is regarded as the father of computers?', '**Charles Babbage** is widely regarded as the **father of computers**, having designed the **Analytical Engine** in the 19th century, which laid the conceptual foundation for the modern programmable computer.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00431', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 1, 'Who is regarded as the father of the modern computer science / first programmer?', '**Ada Lovelace** is widely recognized as the **first computer programmer**, having written the first algorithm intended to be processed by Charles Babbage''s **Analytical Engine** in the 1840s.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00432', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 2, 'What was ENIAC, and why is it historically significant?', '`ENIAC` (**Electronic Numerical Integrator and Computer**) was one of the earliest **general-purpose electronic digital computers**, completed in **1945**, and is historically significant as a pioneering machine of the first generation of computers.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00433', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 3, 'Who founded Microsoft, and in what year?', '**Microsoft** was founded by **Bill Gates and Paul Allen** in **1975**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00434', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 4, 'Who founded Apple Inc., and in what year?', '**Apple Inc.** was founded by **Steve Jobs, Steve Wozniak, and Ronald Wayne** in **1976**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00435', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 5, 'Who founded Google, and in what year?', '**Google** was founded by **Larry Page and Sergey Brin** in **1998**, while they were PhD students at **Stanford University**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00436', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 6, 'Who founded Facebook (now Meta), and in what year?', '**Facebook** was founded by **Mark Zuckerberg**, along with college roommates, in **2004**; the parent company was later renamed **Meta Platforms** in 2021.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00437', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 7, 'Who founded Amazon, and in what year?', '**Amazon** was founded by **Jeff Bezos** in **1994**, initially launching as an online bookstore before expanding into a global e-commerce and cloud-computing company.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00438', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 8, 'What is Aadhaar, and which body issues it?', '**Aadhaar** is a **12-digit unique identification number** issued to residents of India, based on their biometric and demographic data, administered by the **Unique Identification Authority of India (`UIDAI`)**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00439', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 9, 'What is Digital India, and when was it launched?', '**Digital India** is a flagship initiative of the **Government of India**, launched in **2015**, aimed at transforming India into a **digitally empowered society and knowledge economy** by improving online infrastructure and digital literacy.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00440', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 10, 'What is UPI, and which organization operates it in India?', '`UPI` stands for **Unified Payments Interface**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00441', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 11, 'What is BHIM, in the context of Indian digital payments?', '`BHIM` stands for **Bharat Interface for Money**, a mobile payment application developed by the **National Payments Corporation of India (`NPCI`)** that enables users to make simple, quick, and secure transactions using `UPI`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00442', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 12, 'What is the National Payments Corporation of India (NPCI) responsible for?', 'The **National Payments Corporation of India (`NPCI`)** is an umbrella organization that operates **retail payment and settlement systems** in India, including `UPI`, `RuPay`, `IMPS`, and `NEFT`/`NACH`-related infrastructure.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00443', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 13, 'What does RuPay refer to?', '`RuPay` is a **domestic card payment network** established by the **National Payments Corporation of India (`NPCI`)**, created as an indigenous alternative to international networks like `Visa` and `Mastercard`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00444', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 14, 'What does NEFT stand for?', '`NEFT` stands for **National Electronic Funds Transfer**, an electronic payment system in India that enables **one-to-one fund transfers** between bank accounts, processed in batches throughout the day.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00445', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 15, 'What does RTGS stand for?', '`RTGS` stands for **Real Time Gross Settlement**, an electronic funds transfer system used in India for **high-value transactions**, where transfers are settled **individually and instantly**, typically with a minimum transaction threshold.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00446', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 16, 'What does IMPS stand for in Indian banking?', '`IMPS` stands for **Immediate Payment Service**, a real-time, **24x7 interbank electronic funds transfer** system in India, operated by the `NPCI`, allowing instant money transfers via mobile, internet, or `ATM`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00447', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 17, 'What is CDAC, and what is its role in Indian computing?', '`C-DAC` stands for the **Centre for Development of Advanced Computing**, a premier **research and development institution** under India''s **Ministry of Electronics and Information Technology (`MeitY`)**, known for developing the `PARAM` supercomputer series.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00448', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 18, 'What does MeitY stand for?', '`MeitY` stands for the **Ministry of Electronics and Information Technology**, the Indian government ministry responsible for **IT policy, e-governance initiatives, and digital infrastructure development**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00449', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 19, 'What is e-governance?', '**E-governance** refers to the use of **information and communication technology (`ICT`)** by government bodies to deliver public services, share information, and engage with citizens more efficiently and transparently.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00450', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 20, 'What does ICT stand for?', '`ICT` stands for **Information and Communication Technology**, a broad term covering all technologies used to **manage, process, and communicate information**, including computers, networks, and telecommunications.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00451', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 21, 'What is the significance of the term ''Y2K problem/bug''?', 'The **Y2K (Year 2000) problem** referred to a widespread software flaw where programs **stored years using only two digits**, raising fears that systems would misinterpret the year 2000 as 1900, prompting a massive global remediation effort before the millennium changeover.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00452', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 22, 'What is an e-commerce platform? Give an example relevant to India.', 'An **e-commerce platform** is a website or application that facilitates the **buying and selling of goods and services online**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00453', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 23, 'What is artificial intelligence (AI), broadly defined?', '**Artificial Intelligence (`AI`)** is the branch of computer science focused on building systems capable of performing tasks that typically **require human intelligence**, such as learning, reasoning, problem-solving, and perception.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00454', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 24, 'What is machine learning, and how does it relate to AI?', '**Machine Learning (`ML`)** is a **subset of Artificial Intelligence** that enables systems to **automatically learn and improve from data and experience**, without being explicitly programmed for every specific scenario.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00455', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 25, 'What is deep learning, and how does it relate to machine learning?', '**Deep Learning** is a **subset of Machine Learning** that uses **multi-layered artificial neural networks** to model complex patterns in large amounts of data, powering applications like image recognition and natural language processing.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00456', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 26, 'What is a chatbot?', 'A **chatbot** is a software application designed to **simulate human conversation**, typically through text or voice, used in customer service, information retrieval, and virtual assistance.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00457', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 27, 'What is blockchain technology?', '**Blockchain** is a **distributed, decentralized digital ledger** that records transactions across multiple computers in a way that makes the recorded data **resistant to retroactive alteration**, forming the underlying technology behind cryptocurrencies like Bitcoin.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00458', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 28, 'What is cryptocurrency, and give one example?', '**Cryptocurrency** is a form of **digital or virtual currency secured by cryptography**, typically operating on a decentralized blockchain network rather than relying on a central bank.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00459', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 29, 'What is 3D printing?', '**3D printing** (or **additive manufacturing**) is a process of creating a **three-dimensional physical object from a digital design** by building it up layer by layer, using materials such as plastic, resin, or metal.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00460', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 30, 'What is virtual reality (VR)?', '**Virtual Reality (`VR`)** is a **simulated, immersive digital environment** that a user can interact with using specialized equipment, such as a headset, creating the sensation of being physically present in a computer-generated world.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00461', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 31, 'What is augmented reality (AR)?', '**Augmented Reality (`AR`)** overlays **digital information or visuals onto the real-world environment**, typically viewed through a smartphone camera or smart glasses, enhancing rather than replacing the user''s perception of reality.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00462', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 32, 'What is a smart city, in the context of IT and urban planning?', 'A **smart city** uses **information and communication technology (`ICT`) and `IoT` sensors** to improve the efficiency of urban services such as traffic management, energy use, waste management, and public safety.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00463', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 33, 'What is the Digital Signature Certificate (DSC) used for in India?', 'A **Digital Signature Certificate (`DSC`)** is a secure digital key issued by a **Certifying Authority**, used in India to **authenticate the identity of the certificate holder** for online transactions, e-filing of taxes, and e-tendering.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00464', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 34, 'What is GSTN in the context of India''s Goods and Services Tax?', '`GSTN` stands for the **Goods and Services Tax Network**, a nonprofit organization that manages the **IT infrastructure and services** for the implementation of India''s `GST` system, handling registration, returns, and payments.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00465', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 35, 'What is net banking (internet banking)?', '**Net banking** (internet banking) allows customers to **perform banking transactions online** through a bank''s website or app, including fund transfers, bill payments, and account management, without visiting a physical branch.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00466', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 36, 'What is mobile banking, and how does it differ from net banking?', '**Mobile banking** allows customers to conduct banking transactions via a **dedicated mobile application**, often optimized for smartphones.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00467', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 37, 'What is e-KYC, in the context of Indian financial services?', '`e-KYC` stands for **Electronic Know Your Customer**, a process that uses **digital methods** (such as Aadhaar-based authentication) to verify a customer''s identity remotely, without requiring physical document submission.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00468', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 38, 'What is the significance of the term ''Startup India''?', '**Startup India** is a flagship initiative launched by the **Government of India in 2016** to build a strong ecosystem for **nurturing innovation and entrepreneurship**, offering incentives, funding support, and simplified compliance for startups.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00469', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 39, 'What does BPO stand for?', '`BPO` stands for **Business Process Outsourcing**, the practice of **contracting specific business functions or processes** (such as customer support or payroll) to a third-party service provider, often in a different country.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00470', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 40, 'What does KPO stand for, and how does it differ from BPO?', '`KPO` stands for **Knowledge Process Outsourcing**, which involves outsourcing **high-value, knowledge-intensive tasks** (such as research or data analytics), in contrast to `BPO`, which typically covers more routine, process-driven business functions.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00471', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 41, 'What is NASSCOM?', '`NASSCOM` stands for the **National Association of Software and Service Companies**, a premier **trade association representing India''s IT and business process management industry**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00472', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 42, 'What is the significance of IT hubs like Bengaluru in India?', '**Bengaluru**, often called the **''Silicon Valley of India''**, is a major hub for the **information technology and software industry**, hosting the headquarters or major offices of numerous domestic and multinational tech companies.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00473', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 43, 'What is open data, in the context of government and technology?', '**Open data** refers to data that is **made freely available to everyone**, without restrictions on copyright or patents, to be used, reused, and redistributed, often published by governments to promote transparency.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00474', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 44, 'What is the significance of net banking OTP-based two-factor authentication under RBI guidelines?', 'The **Reserve Bank of India (`RBI`)** mandates **additional factor authentication**, commonly an **`OTP`**, for most online card and net-banking transactions in India, adding a layer of security beyond just a password or card details.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00475', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 45, 'What is the Pradhan Mantri Gramin Digital Saksharta Abhiyan (PMGDISHA)?', '`PMGDISHA` is a **Government of India scheme** aimed at making citizens in rural areas **digitally literate**, enabling them to operate computers/digital devices and use the internet for everyday tasks.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00476', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 46, 'What is a data center?', 'A **data center** is a **dedicated facility** used to house computer systems, servers, and associated components such as networking and storage equipment, typically requiring robust power, cooling, and security infrastructure.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00477', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 47, 'What is quantum computing, broadly?', '**Quantum computing** is an emerging computing paradigm that uses principles of **quantum mechanics**, such as superposition and entanglement, processing information using **qubits** instead of classical bits, with the potential to solve certain problems far faster than classical computers.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00478', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 48, 'What is edge computing?', '**Edge computing** is a distributed computing approach that processes data **closer to where it is generated** (at the ''edge'' of the network, near the source/device), rather than relying solely on a centralized data center, reducing latency.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00479', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 49, 'What is 5G technology expected to significantly improve compared to 4G?', '**5G** technology offers significantly **higher data speeds, lower latency, and greater device connection density** compared to `4G`, enabling applications like real-time remote surgery, autonomous vehicles, and massive `IoT` deployments.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00480', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 50, 'What is the significance of the term ''digital divide''?', 'The **digital divide** refers to the **gap between individuals or communities who have access to modern information and communication technology** (like the internet and computers) and those who do not, often correlating with socioeconomic or geographic factors.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00481', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 51, 'What is net metering, in the context of smart technology/renewable energy?', '**Net metering** is a billing mechanism that allows consumers who generate their own electricity (such as from rooftop solar panels) to **feed surplus power back into the grid**, with smart meters tracking and crediting the exchange.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00482', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 52, 'What is RPA (Robotic Process Automation)?', '`RPA` stands for **Robotic Process Automation**, a technology that uses **software ''robots'' (bots) to automate repetitive, rule-based digital tasks**, such as data entry, without requiring changes to existing underlying systems.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00483', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 53, 'What is the significance of the term ''digital footprint''?', 'A **digital footprint** refers to the **trail of data a person leaves behind** while using the internet, including websites visited, social media posts, and online transactions, which can be used to build a profile of their online activity.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00484', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 54, 'What is the significance of ISO in the context of technology standards?', '`ISO` stands for the **International Organization for Standardization**, a global body that develops and publishes **international standards** to ensure quality, safety, and compatibility across industries, including information technology (such as the `ISO/IEC 27001` information security standard).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00485', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 55, 'What is the significance of the term ''open government data'' / National Data Sharing Policy in India?', 'India''s **National Data Sharing and Accessibility Policy (`NDSAP`)** aims to provide **access to government-owned data** for planning, research, and innovation, promoting transparency and the reuse of public datasets through platforms like `data.gov.in`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00486', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 56, 'What is the Common Service Centre (CSC) scheme in India?', '**Common Service Centres (`CSC`s)** are access points that deliver **government and private digital services** (such as Aadhaar enrollment, banking, and certificates) to citizens in rural and remote areas of India.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00487', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 57, 'What is telemedicine?', '**Telemedicine** is the use of **telecommunications technology** to provide clinical healthcare remotely, allowing patients to consult doctors, receive diagnoses, and get prescriptions **without an in-person visit**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00488', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 58, 'What is a fintech company?', 'A **fintech (financial technology) company** uses **innovative technology** to deliver financial services, such as digital payments, lending, or investment management, often more efficiently or accessibly than traditional financial institutions.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00489', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 59, 'What is the significance of the term ''automation'' in the IT industry context?', '**Automation** in IT refers to the use of **technology to perform tasks with minimal human intervention**, ranging from automated software testing to robotic process automation, improving efficiency and reducing manual errors.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00490', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 60, 'What is a Unique Identification Number scheme''s main purpose, as exemplified by Aadhaar?', 'Aadhaar''s main purpose is to provide a **single, verifiable digital identity** for every resident of India, intended to **streamline the delivery of government benefits and services** and reduce duplicate or fraudulent beneficiary records.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00491', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 61, 'What does IT stand for, in the broadest sense?', '`IT` stands for **Information Technology**, broadly referring to the use of **computers, networking, and other physical devices and processes** to create, process, store, secure, and exchange electronic data.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00492', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 62, 'What is the significance of the term ''Make in India'' for electronics/IT manufacturing?', '**Make in India** is a Government of India initiative launched in **2014** to encourage companies to **manufacture products, including electronics and IT hardware, within India**, aiming to boost domestic manufacturing and reduce import dependence.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00493', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 63, 'What is a data protection law, and name India''s relevant legislation.', 'A **data protection law** sets rules for how personal data may be **collected, processed, stored, and shared**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00494', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 64, 'What is the significance of the term ''cashless economy'' in India''s digital push?', 'A **cashless economy** refers to an economic system where **transactions are conducted primarily through digital means** (cards, `UPI`, mobile wallets) rather than physical currency, a goal actively promoted through India''s **Digital India** initiatives.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00495', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 65, 'What is a mobile wallet (e-wallet)? Give an example.', 'A **mobile wallet (e-wallet)** is an application that allows users to **store payment information digitally** and make transactions directly from a smartphone, without needing physical cash or cards.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00496', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 66, 'What does the term ''unicorn'' mean in the startup/technology ecosystem?', 'A **''unicorn''** is a privately held **startup company valued at over US$1 billion**, a term coined in the venture capital industry to describe the rarity of such high-value young companies.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00497', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 67, 'What is the significance of the National Informatics Centre (NIC) in India?', 'The **National Informatics Centre (`NIC`)** is a premier Indian government organization under `MeitY` that provides **IT infrastructure, network services, and e-governance support** to central and state government departments.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00498', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 68, 'What does the abbreviation OTT stand for in media technology?', '`OTT` stands for **Over-The-Top**, referring to **media content and services (such as video streaming) delivered directly to viewers via the internet**, bypassing traditional cable, satellite, or broadcast television providers.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00499', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 69, 'What is the significance of ISRO''s role in India''s satellite/IT infrastructure?', 'The **Indian Space Research Organisation (`ISRO`)** develops and launches **satellites that support India''s communication, navigation (such as `NavIC`), and internet connectivity infrastructure**, in addition to its broader space research mission.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('compaware-q00500', 'computer-awareness-bank', 'IT & Technology General Knowledge', 6, 70, 'What is NavIC, India''s satellite navigation system?', '`NavIC` stands for **Navigation with Indian Constellation**, an **indigenous regional satellite navigation system** developed by `ISRO`, providing accurate positioning services over India and the surrounding region, similar in purpose to the American `GPS`.', '2026-11-14T06:17:56.365Z');
